Object.assign(window.TEM8_DICTIONARY, {"puzzle":{"oxford":{"phon":"ˈpʌzl","pos":"noun","senses":[{"en":"a game, etc. that you have to think about carefully in order to answer it or do it","cn":"谜；智力游戏","ex":{"en":"a crossword puzzle","cn":"纵横字谜"}},{"en":"something that is difficult to understand or explain","cn":"不解之谜；疑问","g":"[usually singular]","ex":{"en":"The deeper meaning of the poem remains a puzzle.","cn":"这首诗的深层含义仍然是个谜。"}},{"en":"a picture printed on cardboard (= very thick, stiff card) or wood, that has been cut up into a lot of small pieces of different shapes that you have to fit together again","cn":"拼图；拼板玩具","lab":"especially North American English"},{"en":"to make somebody feel confused because they do not understand something","cn":"迷惑；使困惑","ex":{"en":"What puzzles me is why he left the country without telling anyone.","cn":"令我不解的是，他为什么悄悄地离开了这个国家。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使迷惑；使困惑","en":"If something puzzles you, you do not understand it and feel confused.","ex":{"en":"My sister puzzles me and causes me anxiety.","cn":"我妹妹总让我捉摸不透，弄得我焦虑不安。"}},{"pos":"VERB 动词","cn":"对…苦苦思索；因…大伤脑筋","en":"If you puzzle over something, you try hard to think of the answer to it or the explanation for it.","ex":{"en":"In rehearsing Shakespeare, I puzzle over the complexities of his verse and prose.","cn":"在排演莎士比亚的戏剧时，其中诗句和散文的复杂让我大伤脑筋。"}},{"pos":"N-COUNT 可数名词","cn":"难题；智力问题（或游戏、玩具）；谜","en":"A puzzle is a question, game, or toy which you have to think about carefully in order to answer it correctly or put it together properly.","ex":{"en":"...a word puzzle.","cn":"字谜"}},{"pos":"N-SING 单数名词","cn":"令人费解的人；令人困惑的事物","en":"You can describe a person or thing that is hard to understand as a puzzle .","ex":{"en":"Data from Voyager II has presented astronomers with a puzzle about why our outermost planet exists","cn":"“旅行者二号”发回的数据给天文学家们提出了一个难题：离我们最远的那颗行星为什么会存在。"}},{"pos":"","cn":"","en":"相关词组：puzzle out"}]},"media":{"img":["media/pic/puzzles_comp.jpg","media/thumb/crossword.jpg"],"uk":"media/uk/puzzle__gb_1.mp3","us":"media/us/puzzle__us_1.mp3"},"examples":[{"en":"What puzzles me is why he left the country without telling anyone.","cn":"令我不解的是，他为什么悄悄地离开了这个国家。"},{"en":"He was trying to puzzle out why he had been brought to the house.","cn":"他想弄明白自己为何被带到这所房子。"}]},"punished":{"lemma":"punish"},"pupil":{"oxford":{"phon":"ˈpjuːpl","pos":"noun","senses":[{"en":"a person who is being taught, especially a child in a school","cn":"学生；（尤指）小学生","lab":"especially British English, becoming old-fashioned，，","ex":{"en":"school pupils","cn":"小学生"}},{"en":"a person who is taught artistic, musical, etc. skills by an expert","cn":"弟子；门生；门徒","ex":{"en":"Charpentier took pupils and taught them composition and accompanying.","cn":"卡彭蒂埃招收学生并教他们作曲和伴奏。"}},{"en":"the small round black area at the centre of the eye","cn":"瞳孔；眸子；瞳仁","ex":{"en":"Her pupils were dilated.","cn":"她的瞳孔扩大了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"学生；小学生","en":"The pupils of a school are the children who go to it.","ex":{"en":"Over a third of those now at secondary school in Wales attend schools with over 1,000 pupils","cn":"威尔士现在的初中生中有1/3以上的人就读的学校学生总数超过1,000人。"}},{"pos":"N-COUNT 可数名词","cn":"弟子；门生","en":"A pupil of a painter, musician, or other expert is someone who studies under that expert and learns his or her skills.","ex":{"en":"After his education, Goldschmidt became a pupil of the composer Franz Schreker.","cn":"学业结束后，戈尔德施米特成了作曲家弗朗兹·施雷克尔的学生。"}},{"pos":"N-COUNT 可数名词","cn":"瞳孔","en":"The pupils of your eyes are the small, round, black holes in the centre of them."}]},"media":{"uk":"media/uk/pupil__gb_1.mp3","us":"media/us/pupil__us_1.mp3","img":["media/ldoce/img/ldoce_086.png"]},"examples":[{"en":"The painting is by a pupil of Rembrandt.","cn":"这幅画为伦勃朗的一位弟子所作。"},{"en":"How many pupils does the school have?","cn":"这所小学有多少学生？"}]},"purchasing":{"media":{"uk":"media/uk/purchasing__gb_1.mp3","us":"media/us/purchasing__us_1.mp3"},"oxford":{"phon":"ˈpɜːtʃəsɪŋ","pos":"noun","senses":[{"en":"the activity of buying things, especially for a company","cn":"购买；采购","ex":{"en":"the company’s purchasing manager","cn":"公司采购经理"}}]},"base":"purchase"},"pupils":{"lemma":"pupil"},"pushed":{"oxford":{"phon":"pʊʃt","pos":"adjective","senses":[{"en":"having difficulty doing something","cn":"有困难；难于；有难处","ex":{"en":"You'll be hard pushed to finish this today.","cn":"要你今天做完这件事会很难。"}},{"en":"not having enough of something","cn":"短缺；缺乏；不足","ex":{"en":"to be pushed for money/time","cn":"缺少资金／时间"}},{"en":"busy","cn":"忙碌","ex":{"en":"I know you're pushed, but can you make tomorrow's meeting?","cn":"我知道你很忙，可是你能不能参加明天的会议？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（时间或金钱）紧缺的，短缺的，拮据的","en":"If you are pushed for something such as time or money, you do not have enough of it.","ex":{"en":"He's going to be a bit pushed for money.","cn":"他手头会有点儿紧。"}},{"pos":"PHRASE 短语","cn":"难于（做某事）","en":"If you are hard pushed to do something, you find it very difficult to do it.","ex":{"en":"I'd be hard pushed to teach him anything.","cn":"我发觉很难教他什么东西。"}}]},"media":{"uk":"media/uk/pushed__gb_1.mp3","us":"media/us/pushed__us_1.mp3"},"examples":[{"en":"I know you're pushed, but can you make tomorrow's meeting?","cn":"我知道你很忙，可是你能不能参加明天的会议？"},{"en":"You'll be hard pushed to finish this today.","cn":"要你今天做完这件事会很难。"}],"base":"push"},"purposeless":{"media":{"uk":"media/uk/purposeless__gb_1.mp3","us":"media/us/purposeless__us_1.mp3"},"oxford":{"phon":"ˈpɜːpəsləs","pos":"adjective","senses":[{"en":"having no meaning, use or clear aim","cn":"无目的的；无用的；无意义的","ex":{"en":"purposeless destruction","cn":"盲目的破坏"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"漫无目的的；无意义的","en":"If an action is purposeless, it does not seem to have a sensible purpose.","ex":{"en":"Time may also be wasted in purposeless meetings","cn":"时间也可能浪费在毫无意义的会议当中。"}}]},"examples":[{"en":"purposeless destruction","cn":"盲目的破坏"},{"en":"hours of purposeless activity","cn":"几小时漫无目的的活动"}]},"punishment":{"media":{"uk":"media/uk/punishment__gb_1.mp3","us":"media/us/punishment__us_1.mp3"},"oxford":{"phon":"ˈpʌnɪʃmənt","pos":"noun","senses":[{"en":"an act or a way of punishing somebody","cn":"惩罚；处罚；刑罚","g":"[uncountable, countable]","ex":{"en":"to inflict/impose/mete out punishment","cn":"予以惩罚"}},{"en":"rough treatment","cn":"粗暴对待；虐待","g":"[uncountable]","ex":{"en":"The carpet by the door takes the most punishment.","cn":"门边的地毯磨损得最厉害。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"处罚；惩罚","en":"Punishment is the act of punishing someone or of being punished.","ex":{"en":"...a group which campaigns against the physical punishment of children","cn":"一个反对体罚儿童的团体"}},{"pos":"N-VAR 可变名词","cn":"处罚（或惩罚）方式","en":"A punishment is a particular way of punishing someone.","ex":{"en":"The government is proposing tougher punishments for officials convicted of corruption","cn":"政府提议对已被定罪的贪污腐败官员实施更为严厉的惩罚。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"粗暴对待；虐待；糟蹋","en":"You can use punishment to refer to severe physical treatment of any kind.","ex":{"en":"Don't expect these types of boot to take the punishment that gardening will give them.","cn":"不要指望能穿着这类靴子去干园艺活儿，它们没那么耐穿耐磨。"}}]},"examples":[{"en":"There is little evidence that harsher punishments deter any better than more lenient ones.","cn":"甚少证据显示严惩比宽待更能遏止犯罪。"},{"en":"The carpet by the door takes the most punishment.","cn":"门边的地毯磨损得最厉害。"}]},"punishing":{"oxford":{"phon":"ˈpʌnɪʃɪŋ","pos":"adjective","senses":[{"en":"long and difficult and making you work hard so you become very tired","cn":"艰难持久的；令人筋疲力尽的","ex":{"en":"The President has a punishing schedule for the next six months.","cn":"总统今后六个月的工作日程十分繁忙。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"繁重费力的；艰难的","en":"A punishing schedule, activity, or experience requires a lot of physical effort and makes you very tired or weak.","ex":{"en":"He claimed his punishing work schedule had made him resort to taking the drug","cn":"他声称繁重的工作安排使他不得不依靠服药来维持精力。"}}]},"media":{"uk":"media/uk/punishing__gb_1.mp3","us":"media/us/punishing__us_1.mp3"},"examples":[{"en":"The President has a punishing schedule for the next six months.","cn":"总统今后六个月的工作日程十分繁忙。"},{"en":"He set himself a punishing schedule of conferences.","cn":"他为自己定下了繁忙的会议日程。"}],"base":"punish"},"punish":{"oxford":{"phon":"ˈpʌnɪʃ","pos":"verb","senses":[{"en":"to make somebody suffer because they have broken the law or done something wrong","cn":"处罚；惩罚","g":"[intransitive, transitive]","ex":{"en":"Those responsible for this crime will be severely punished.","cn":"犯下这宗罪行的人将受到严厉惩罚。"}},{"en":"to set the punishment for a particular crime","cn":"对…判罪；判定…的处罚方式","g":"[transitive]","ex":{"en":"In those days murder was always punished with the death penalty.","cn":"那个时候，谋杀总是判死罪。"}},{"en":"to blame yourself for something that has happened","cn":"责怪（自己）；自责","g":"[transitive]"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"处罚，惩罚（犯错之人）","en":"To punish someone means to make them suffer in some way because they have done something wrong.","ex":{"en":"I don't believe that George ever had to punish the children","cn":"我认为乔治根本没有必要处罚孩子们。"}},{"pos":"VERB 动词","cn":"惩罚（犯罪之人）；对…判罪","en":"To punish a crime means to punish anyone who commits that crime.","ex":{"en":"The government voted to punish corruption in sport with up to four years in jail","cn":"政府经表决后决定对体育界的舞弊行为最高将处以4年监禁。"}}]},"media":{"uk":"media/uk/punish__gb_1.mp3","us":"media/us/punish__us_1.mp3"},"examples":[{"en":"My parents used to punish me by not letting me watch TV.","cn":"过去我父母常以不让我看电视来惩罚我。"},{"en":"He was punished for refusing to answer their questions.","cn":"他拒不回答他们的问题，受到了惩罚。"}]},"pumping":{"lemma":"pump"},"put":{"media":{"uk":"media/uk/put__gb_1.mp3","us":"media/us/put__us_1.mp3"},"oxford":{"phon":"pʊt","pos":"verb","senses":[{"en":"to move something into a particular place or position","cn":"放；安置","sc":"in place/position","ex":{"en":"Put the cases down there, please.","cn":"请把箱子搁在那边。"}},{"en":"to move something into a particular place or position using force","cn":"猛推；用力插入","sc":"in place/position","ex":{"en":"He put his fist through a glass door.","cn":"他用拳头砸穿了玻璃门。"}},{"en":"to cause somebody/something to go to a particular place","cn":"将…送往；使…前往","sc":"in place/position","ex":{"en":"Her family put her into a nursing home.","cn":"她的家人把她送进了一家疗养院。"}},{"en":"to attach or fix something to something else","cn":"使与…连接；安装","sc":"attach","ex":{"en":"We had to put new locks on all the doors.","cn":"我们只好把所有的门都安上新锁。"}},{"en":"to write something or make a mark on something","cn":"（在…上）书写，记，做标记","sc":"write","ex":{"en":"Put your name here.","cn":"在这里填上姓名。"}},{"en":"to bring somebody/something into the state or condition mentioned","cn":"使处于（某状态或情况）","sc":"into state/condition","ex":{"en":"I was put in charge of the office.","cn":"他们让我负责管理这个办公室。"}},{"en":"to make somebody/something feel something or be affected by something","cn":"使感觉到；使受到…的影响","sc":"affect somebody/something","ex":{"en":"Her new job has put a great strain on her.","cn":"她的新工作使她感到负担很重。"}},{"en":"to express or state something in a particular way","cn":"说；表达","sc":"express","ex":{"en":"She put it very tactfully.","cn":"她的话说得很巧妙。"}},{"en":"to give or attach a particular level of importance, trust, value, etc. to something","cn":"给予（重视、信任、价值等）","sc":"give value/rank","ex":{"en":"Our company puts the emphasis on quality.","cn":"我们公司重视质量。"}},{"en":"to consider somebody/something to belong to the class or level mentioned","cn":"把…视为（或列为）","sc":"give value/rank","ex":{"en":"I'd put her in the top rank of modern novelists.","cn":"我认为她应属于一流的当代小说家。"}},{"en":"to throw the shot","cn":"推（铅球）","sc":"in sport"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"放；置；使处于某位置","en":"When you put something in a particular place or position, you move it into that place or position.","ex":{"en":"Leaphorn put the photograph on the desk","cn":"利普霍恩把照片放在书桌上。"}},{"pos":"VERB 动词","cn":"将（某人）安置于（某处）","en":"If you put someone somewhere, you cause them to go there and to stay there for a period of time.","ex":{"en":"Rather than put him in the hospital, she had been caring for him at home","cn":"她没有让他住在医院，而是一直在家里照顾他。"}},{"pos":"VERB 动词","cn":"使处于特定状态（或境地）","en":"To put someone or something in a particular state or situation means to cause them to be in that state or situation.","ex":{"en":"This is going to put them out of business","cn":"这将会使他们破产。"}},{"pos":"VERB 动词","cn":"使接受；使受影响","en":"To put something on people or things means to cause them to have it, or to cause them to be affected by it.","ex":{"en":"The ruling will put extra pressure on health authorities to change working practices and shorten hours","cn":"该判决将给卫生部门施加更多的压力促使其改变工作惯例，缩短工作时间。"}},{"pos":"VERB 动词","cn":"把（信任等）寄托于","en":"If you put your trust, faith, or confidence in someone or something, you trust them or have faith or confidence in them.","ex":{"en":"He had decided long ago that he would put his trust in socialism when the time came","cn":"很久以前他就决定时机成熟时会寄希望于社会主义。"}},{"pos":"VERB 动词","cn":"投入，花费（时间、体力或精力）","en":"If you put time, strength, or energy into an activity, you use it in doing that activity.","ex":{"en":"We're not saying that activists should put all their effort and time into party politics","cn":"我们并不是说活动家应该把所有的精力和时间都用到政党政治上。"}},{"pos":"VERB 动词","cn":"投入（资金）","en":"If you put money into a business or project, you invest money in it.","ex":{"en":"Investors should consider putting some money into an annuity","cn":"投资者们应当考虑存一些年金。"}},{"pos":"VERB 动词","cn":"表述；表达","en":"When you put an idea or remark in a particular way, you express it in that way. You can use expressions like to put it simply and to put it bluntly before saying something when you want to explain how you are going to express it.","ex":{"en":"I had already met Pete a couple of times through — how should I put it — friends in low places","cn":"我已经见过皮特几次了，是通过——怎么说呢——一些社会下层的朋友见的。"}},{"pos":"VERB 动词","cn":"提出（问题）","en":"When you put a question to someone, you ask them the question.","ex":{"en":"Is this fair? Well, I put that question today to Deputy Counsel Craig Gillen","cn":"这公平吗？我今天向副顾问克雷格·吉伦提出这个问题。"}},{"pos":"VERB 动词","cn":"对（事件）作出说明；提出（意见、建议）","en":"If you put a case, opinion, or proposal, you explain it and list the reasons why you support or believe it.","ex":{"en":"He always put his point of view with clarity and with courage","cn":"他总是清楚而勇敢地提出自己的观点。"}},{"pos":"VERB 动词","cn":"给…定价（或估值）；把…归(类)","en":"If you put something at a particular value or in a particular category, you consider that it has that value or that it belongs in that category.","ex":{"en":"I would put her age at about 50 or so","cn":"我认为她的年龄在50岁上下。"}},{"pos":"VERB 动词","cn":"写上；记上；键入；印上","en":"If you put written information somewhere, you write, type, or print it there.","ex":{"en":"Mary's family were so pleased that they put an announcement in the local paper to thank them","cn":"玛丽的家人很高兴，就在当地的报纸上登了一则启事来感谢他们。"}},{"pos":"PHRASE 短语","cn":"欺骗；愚弄","en":"If someone puts one over on you, they make you do or believe something by telling you things that are not true.","ex":{"en":"He considered himself a crafty man — a man would have to get up very early in the morning to put one over on Alf Tandy.","cn":"他觉得自己太狡猾了——为了愚弄一下阿尔夫·坦迪通常得早上很早起床。"}},{"pos":"PHRASE 短语","cn":"指出；说明","en":"If you put it to someone that something is true, you suggest that it is true, especially when you think that they will be unwilling to admit this.","ex":{"en":"But I put it to you that they're useless","cn":"但是我告诉你它们是没用的。"}},{"pos":"PHRASE 短语","cn":"把…放在一起；组合","en":"If you say that something is bigger or better than several other things put together, you mean that it is bigger or has more good qualities than all of those other things if they are added together.","ex":{"en":"London has more pubs and clubs than the rest of the country put together.","cn":"伦敦的酒馆和俱乐部比英国其他地区所有的加在一起还要多。"}},{"pos":"PHRASE 短语","cn":"（表示同意、祝贺等的用语）握个手吧","en":"You say 'Put it there!' to someone when you are asking them to shake hands with you, because you agree with them or want to congratulate them.","ex":{"en":"Put it there, Pal, put it there!","cn":"握个手，老弟，祝贺你！"}},{"pos":"","cn":"","en":"相关词组：put about put across put around put aside put away put back put by put down put down as put down for put down to put forth put forward put in put off put on put onto put out put over put round put through put together put up put up for put up to put up with"}]},"examples":[{"en":"A local businessman has put up the £500 000 needed to save the club.","cn":"一位当地的商人拿出了拯救该俱乐部所需的 50 万英镑。"},{"en":"Put simply, we accept their offer or go bankrupt.","cn":"简单地说吧，我们要么接受他们的条件，要么破产。"}]},"publisher":{"oxford":{"phon":"ˈpʌblɪʃə(r)","pos":"noun","senses":[{"en":"a person or company that prepares and prints books, magazines, newspapers or electronic products and makes them available to the public","cn":"出版人（或机构）；发行人（或机构）","ex":{"en":"Several publishers are competing in the same market.","cn":"几家出版公司正在同一市场上竞争。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"出版者；出版社；出版公司","en":"A publisher is a person or a company that publishes books, newspapers, or magazines.","ex":{"en":"The publishers planned to produce the journal on a weekly basis.","cn":"出版者计划将该期刊定为周刊。"}}]},"media":{"uk":"media/uk/publisher__gb_1.mp3","us":"media/us/publisher__us_1.mp3"}},"purely":{"media":{"uk":"media/uk/purely__gb_1.mp3","us":"media/us/purely__us_1.mp3"},"oxford":{"phon":"ˈpjʊəli","pos":"adverb","senses":[{"en":"only; completely","cn":"仅仅；完全","ex":{"en":"I saw the letter purely by chance.","cn":"我看见这封信纯属偶然。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"仅仅；完全","en":"You use purely to emphasize that the thing you are mentioning is the most important feature or that it is the only thing which should be considered.","ex":{"en":"It is a racing machine, designed purely for speed","cn":"那是一个比赛用的机器，完全是为提高速度设计的。"}},{"pos":"PHRASE 短语","cn":"纯粹地；不折不扣地","en":"You use purely and simply to emphasize that the thing you are mentioning is the only thing involved.","ex":{"en":"If Arthur was attracted here by the prospects of therapy, John came down purely and simply to make money","cn":"如果阿瑟是被这种疗法的前景吸引到此，那么约翰则纯粹是为了赚钱而来。"}}]},"examples":[{"en":"The charity is run on a purely voluntary basis.","cn":"这个慈善团体完全是义务性质的。"},{"en":"She took the job purely and simply for the money.","cn":"她做这份工作图的就是钱。"}]},"publish":{"media":{"uk":"media/uk/publish__gb_1.mp3","us":"media/us/publish__us_1.mp3"},"oxford":{"phon":"ˈpʌblɪʃ","pos":"verb","senses":[{"en":"to produce a book, magazine, CD-ROM, etc. and sell it to the public","cn":"出版；发行","g":"[transitive]","ex":{"en":"to publish a book/novel/magazine/paper","cn":"出版书／小说／杂志／论文"}},{"en":"to print a letter, an article, etc. in a newspaper or magazine","cn":"（在报刊）发表，刊登，登载","g":"[transitive]","ex":{"en":"to publish a story/letter/comment/review","cn":"刊载小说／信件／评论／述评"}},{"en":"to make information available to the public","cn":"公布；发布","g":"[transitive]","ex":{"en":"to publish work/research/results","cn":"发布著作／研究／成果"}},{"en":"to have your work printed and sold to the public","cn":"发表（作品）；使（作品）出版","g":"[transitive, intransitive]","ex":{"en":"University teachers are under pressure to publish.","cn":"大学教师有发表作品的压力。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"出版；发行","en":"When a company publishes a book or magazine, it prints copies of it, which are sent to shops to be sold.","ex":{"en":"They publish reference books","cn":"他们出版工具书。"}},{"pos":"VERB 动词","cn":"刊登；登载","en":"When the people in charge of a newspaper or magazine publish a piece of writing or a photograph, they print it in their newspaper or magazine.","ex":{"en":"The ban was imposed after the magazine published an article satirising the government","cn":"这家杂志刊登了一篇讽刺政府的文章后被停刊。"}},{"pos":"VERB 动词","cn":"发表；出版","en":"If someone publishes a book or an article that they have written, they arrange to have it published.","ex":{"en":"John Lennon found time to publish two books of his humorous prose.","cn":"约翰·列侬抽时间出版了两本幽默散文。"}},{"pos":"VERB 动词","cn":"公布；发布","en":"If you publish information or an opinion, you make it known to the public by having it printed in a newspaper, magazine, or official document.","ex":{"en":"The demonstrators called on the government to publish a list of registered voters.","cn":"游行者呼吁政府公布注册选民的名单。"}}]},"examples":[{"en":"Most of our titles are also published on CD-ROM.","cn":"我们的大部分书籍也制成光盘发行。"},{"en":"Pictures of the suspect were published in all the daily papers.","cn":"嫌疑人的照片刊登在各家日报上了。"}]},"pudding":{"media":{"uk":"media/uk/pudding__gb_1.mp3","us":"media/us/pudding__us_1.mp3"},"oxford":{"phon":"ˈpʊdɪŋ","pos":"noun","senses":[{"en":"a sweet dish eaten at the end of a meal","cn":"（餐末的）甜食，甜点","lab":"British English","ex":{"en":"What's for pudding?","cn":"有什么甜点？"}},{"en":"a hot sweet dish, often like a cake, made from flour, fat and eggs with fruit, jam, etc. in or on it","cn":"热布丁糕（用面粉、油、蛋制作，加水果、果酱等）","lab":"British English","ex":{"en":"treacle pudding","cn":"糖浆布丁"}},{"en":"a hot dish like a pie with soft pastry made from flour, fat and eggs and usually filled with meat","cn":"热布丁饼（用面粉、油、蛋制作，通常用肉填充）","lab":"British English","ex":{"en":"a steak and kidney pudding","cn":"牛肉腰子布丁"}},{"en":"a cold dessert (= a sweet dish) like cream that tastes of fruit, chocolate, etc.","cn":"冷布丁（甜食，有水果、巧克力等口味）","lab":"especially North American English","ex":{"en":"chocolate pudding","cn":"巧克力布丁"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"布丁","en":"A pudding is a cooked sweet food made with flour, fat, and eggs, and usually served hot.","ex":{"en":"...a cherry sponge pudding with warm custard.","cn":"涂着热蛋奶沙司的樱桃松糕布丁"}},{"pos":"N-VAR 可变名词","cn":"（一餐中的）甜点，甜食","en":"Some people refer to the sweet course of a meal as the pudding.","ex":{"en":"...a menu featuring canapes, a starter, a main course and a pudding","cn":"一份包含开胃面包、头道菜、主菜和甜点的菜单"}},{"pos":"PHRASE 短语","cn":"布丁好坏，不尝不知；试过才知好坏","en":"If you say the proof of the pudding or the proof of the pudding is in the eating, you mean that something new can only be judged to be good or bad after it has been tried or used."}]},"examples":[{"en":"I haven't made a pudding today.","cn":"我今天没做甜点。"},{"en":"What's for pudding?","cn":"有什么甜点？"}]},"pushy":{"media":{"uk":"media/uk/pushy__gb_1.mp3","us":"media/us/pushy__us_1.mp3"},"oxford":{"phon":"ˈpʊʃi","pos":"adjective","senses":[{"en":"trying hard to get what you want, especially in a way that seems rude","cn":"执意强求的；死缠硬磨的","ex":{"en":"a pushy salesman","cn":"纠缠不休的推销员"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"固执己见的；一意孤行的；爱出风头的","en":"If you describe someone as pushy, you mean that they try in a forceful way to get things done as they would like or to increase their status or influence.","ex":{"en":"She was a confident and pushy young woman","cn":"她是个自信又固执己见的年轻女性。"}}]},"examples":[{"en":"a pushy salesman","cn":"纠缠不休的推销员"}]},"push":{"media":{"uk":"media/uk/push__gb_1.mp3","us":"media/us/push__us_1.mp3"},"oxford":{"phon":"pʊʃ","pos":"verb","senses":[{"en":"to use your hands, arms or body in order to make somebody/something move forward or away from you; to move part of your body into a particular position","cn":"推动（人或物）；移动（身体部位）","g":"[intransitive, transitive]","sc":"using hands/arms/body","ex":{"en":"We pushed and pushed but the piano wouldn't move.","cn":"我们推了又推，但钢琴一动不动。"}},{"en":"to use force to move past somebody/something using your hands, arms, etc.","cn":"推进（道路）；挤开","g":"[intransitive, transitive]","sc":"using hands/arms/body","ex":{"en":"People were pushing and shoving to get to the front.","cn":"人们推推搡搡，向最前面挤。"}},{"en":"to press a switch, button, etc., for example in order to make a machine start working","cn":"按；揿；摁","g":"[transitive]","sc":"switch/button","ex":{"en":"I pushed the button for the top floor.","cn":"我按了到顶层的按钮。"}},{"en":"to affect something so that it reaches a particular level or state","cn":"推动，促使（达到某程度或状态）","g":"[transitive]","sc":"affect something","ex":{"en":"This development could push the country into recession.","cn":"这种新情况可能使国家陷入萧条。"}},{"en":"to persuade or encourage somebody to do something that they may not want to do","cn":"说服；劝解；鼓励；敦劝","g":"[transitive]","sc":"persuade","ex":{"en":"He made it clear that he would resist any attempt to push him into early retirement.","cn":"他明确表示，他将抵制任何迫使他提前退休的企图。"}},{"en":"to make somebody work hard","cn":"鞭策；督促","g":"[transitive]","sc":"work hard","ex":{"en":"The music teacher really pushes her pupils.","cn":"这个音乐老师对学生督促得很严。"}},{"en":"to put pressure on somebody and make them angry or upset","cn":"迫使…生气（或不安）","g":"[transitive]","lab":"informal","sc":"put pressure on somebody","ex":{"en":"Her parents are very tolerant, but sometimes she pushes them too far.","cn":"她的父母十分宽容，但她有时也让他们忍无可忍。"}},{"en":"to try hard to persuade people to accept or agree with a new idea, buy a new product, etc.","cn":"力劝…接受；推销","g":"[transitive]","lab":"informal","sc":"new idea/product","ex":{"en":"The interview gave him a chance to push his latest movie.","cn":"这次采访使他有机会推销他的新电影。"}},{"en":"to sell illegal drugs","cn":"贩卖毒品","g":"[transitive]","lab":"informal","sc":"sell drugs"},{"en":"to move forward quickly through an area","cn":"挺进；推进","g":"[intransitive]","sc":"of army","ex":{"en":"The army pushed (on) towards the capital.","cn":"军队向首都挺进。"}},{"en":"an act of pushing something/somebody","cn":"推；搡","lab":"figurative","sc":"using hands/arms/body","ex":{"en":"She gave him a gentle push.","cn":"她轻轻地推了他一下。"},"pos":"noun"},{"en":"a large and determined military attack","cn":"进攻；攻势；挺进","lab":"figurative","sc":"of army","ex":{"en":"a final push against the enemy","cn":"对敌军的最后猛攻"},"pos":"noun"},{"en":"a determined effort to achieve something","cn":"矢志的追求；坚定的努力","sc":"effort","ex":{"en":"The push for reform started in 2007.","cn":"推行改革的努力始于 2007 年。"},"pos":"noun"},{"en":"an act of encouraging somebody to do something","cn":"鼓励；激励","sc":"effort","ex":{"en":"He wants to open his own business, but needs a push in the right direction to get him started.","cn":"他想创业，但还需要适当的鼓励助他起步。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"推；搡；推开","en":"When you push something, you use force to make it move away from you or away from its previous position.","ex":{"en":"The woman pushed back her chair and stood up","cn":"那女人把椅子往后一推站了起来。"}},{"pos":"VERB 动词","cn":"用力挤过","en":"If you push through things that are blocking your way or push your way through them, you use force in order to move past them.","ex":{"en":"I pushed through the crowds and on to the escalator","cn":"我挤出人群，踏上了自动扶梯。"}},{"pos":"VERB 动词","cn":"（部队）开进，挺进","en":"If an army pushes into a country or area that it is attacking or invading, it moves further into it.","ex":{"en":"One detachment pushed into the eastern suburbs towards the airfield","cn":"一支小分队开进了东部郊区向飞机场挺进。"}},{"pos":"VERB 动词","cn":"推动（增长或降低）","en":"To push a value or amount up or down means to cause it to increase or decrease.","ex":{"en":"Any shortage could push up grain prices","cn":"任何一种短缺都会抬高粮食价格。"}},{"pos":"VERB 动词","cn":"推行；推进；使发展","en":"If someone or something pushes an idea or project in a particular direction, they cause it to develop or progress in a particular way.","ex":{"en":"We are continuing to push the business forward","cn":"我们正在继续推进业务的发展。"}},{"pos":"VERB 动词","cn":"鼓励；督促；逼迫","en":"If you push someone to do something or push them into doing it, you encourage or force them to do it.","ex":{"en":"She thanks her parents for keeping her in school and pushing her to study","cn":"她感谢父母送她上学并督促她学习。"}},{"pos":"VERB 动词","cn":"努力争取；力劝","en":"If you push for something, you try very hard to achieve it or to persuade someone to do it.","ex":{"en":"Britain's health experts are pushing for a ban on all cigarette advertising","cn":"英国的健康专家正努力争取取缔任何形式的香烟广告。"}},{"pos":"VERB 动词","cn":"力劝接受；极力宣传；推销","en":"If someone pushes an idea, a point, or a product, they try in a forceful way to convince people to accept it or buy it.","ex":{"en":"Ministers will push the case for opening the plant","cn":"部长们将极力劝说人们接受开办工厂一事。"}},{"pos":"VERB 动词","cn":"贩卖（毒品）","en":"When someone pushes drugs, they sell them illegally.","ex":{"en":"She was sent for trial yesterday accused of pushing drugs.","cn":"她因被控贩毒昨天被送交法院接受审判。"}},{"pos":"VERB 动词","cn":"（行为或声明）冒险，走极端","en":"If you say that someone is pushing it, you mean that their actions or claims are rather excessive or risky.","ex":{"en":"I think that he was pushing it a bit when he said it was the best stadium in the world.","cn":"他说这是世界上最好的体育场，我觉得说得有些过头。"}},{"pos":"PHRASE 短语","cn":"被解雇；断绝关系","en":"If you get the push or are given the push, you are told that you are not wanted any more, either in your job or by someone you are having a relationship with.","ex":{"en":"Two cabinet ministers also got the push.","cn":"两位内阁大臣也被撤职了。"}},{"pos":"","cn":"","en":"to push the boat out→see: ; to push your luck→see: ; if push comes to shove→see: ;"},{"pos":"","cn":"","en":"相关词组：push ahead push around push aside push forward push in push off push on push over push through"}]},"examples":[{"en":"Her parents are very tolerant, but sometimes she pushes them too far.","cn":"她的父母十分宽容，但她有时也让他们忍无可忍。"},{"en":"He is a performer who consistently pushes the envelope of TV comedy.","cn":"他是一个在电视喜剧表演中不断寻求突破的演员。"}]},"purchase":{"media":{"uk":"media/uk/purchase__gb_1.mp3","us":"media/us/purchase__us_1.mp3"},"oxford":{"phon":"ˈpɜːtʃəs","pos":"verb","senses":[{"en":"to buy something","cn":"买；购买；采购","lab":"figurative","ex":{"en":"Please ensure that you purchase your ticket in advance.","cn":"请务必提前买票。"}},{"en":"the act or process of buying something","cn":"购买；采购","g":"[uncountable, countable]","lab":"especially British English","ex":{"en":"to make a purchase (= buy something)","cn":"采购"},"pos":"noun"},{"en":"something that you have bought","cn":"购买的东西；购买项目","g":"[countable]","ex":{"en":"major purchases, such as a new car","cn":"新汽车之类的巨额购买项目"},"pos":"noun"},{"en":"a strong hold on something with the hands or feet, for example when you are climbing","cn":"握紧；抓牢；蹬稳","g":"[uncountable, singular]","lab":"specialist","ex":{"en":"She tried to get a purchase on the slippery rock.","cn":"她设法抓牢光滑的岩石。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"买；购买；采购","en":"When you purchase something, you buy it.","ex":{"en":"He purchased a ticket and went up on the top deck","cn":"他买了一张票，然后上到顶层甲板。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"购买行为","en":"The purchase of something is the act of buying it.","ex":{"en":"Some of the receipts had been for the purchase of cars.","cn":"其中一些收据是购买汽车时开的。"}},{"pos":"N-COUNT 可数名词","cn":"所购之物；购置物","en":"A purchase is something that you buy.","ex":{"en":"She opened the tie box and looked at her purchase. It was silk, with maroon stripes.","cn":"她打开领带盒，看着她买回的东西：一条带有褐红色条纹的丝制领带。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"紧握；牢牢抓住","en":"If you get a purchase on something, you manage to get a firm grip on it.","ex":{"en":"I got a purchase on the rope and pulled","cn":"我紧抓住绳子，用力去拉。"}}]},"examples":[{"en":"The company has just announced its £27 million purchase of Park Hotel.","cn":"这家公司刚刚宣布以 2 700 万英镑买下了帕克酒店。"},{"en":"They purchased the land for $1 million.","cn":"他们以 100 万元买下了这块土地。"}]},"puzzlement":{"oxford":{"phon":"ˈpʌzlmənt","pos":"noun","senses":[{"en":"a feeling of being confused because you do not understand something","cn":"迷惘；困惑","ex":{"en":"She frowned in puzzlement.","cn":"她迷惑地蹙着眉。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"迷惑；困惑","en":"Puzzlement is the confusion that you feel when you do not understand something.","ex":{"en":"He frowned in puzzlement.","cn":"他困惑地皱着眉头。"}}]},"media":{"uk":"media/uk/puzzlement__gb_1.mp3","us":"media/us/puzzlement__us_1.mp3"},"examples":[{"en":"She frowned in puzzlement.","cn":"她迷惑地蹙着眉。"}]},"puff":{"media":{"uk":"media/uk/puff__gb_1.mp3","us":"media/us/puff__us_1.mp3"},"oxford":{"phon":"pʌf","pos":"verb","senses":[{"en":"to be smoking a cigarette, pipe, etc.","cn":"吸，抽（香烟、烟斗等）","g":"[intransitive, transitive]","ex":{"en":"He puffed (away) on his pipe.","cn":"他（一口一口地）吸着烟斗。"}},{"en":"to make smoke or steam blow out in clouds; to blow out in clouds","cn":"使喷出，冒出（烟或蒸汽）","g":"[transitive, intransitive]","ex":{"en":"Chimneys were puffing out clouds of smoke.","cn":"烟囱冒着滚滚浓烟。"}},{"en":"to breathe loudly and quickly, especially after you have been running","cn":"急促喘息；气喘吁吁","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"I was starting to puff a little from the climb.","cn":"爬坡弄得我有点喘息起来。"}},{"en":"to move in a particular direction, sending out small clouds of smoke or steam","cn":"喷着汽（或烟）移动","g":"[intransitive]","ex":{"en":"The train puffed into the station.","cn":"火车喷着蒸汽驶进车站。"}},{"en":"an act of breathing in something such as smoke from a cigarette, or drugs","cn":"吸，抽（把气体经口或鼻引到体内的动作）","g":"[countable]","ex":{"en":"He had a few puffs at the cigar.","cn":"他吸了几口雪茄。"},"pos":"noun"},{"en":"a small amount of air, smoke, etc. that is blown from somewhere","cn":"（烟、气等的）一缕，少量","g":"[countable]","lab":"figurative","ex":{"en":"a puff of wind","cn":"一丝清风"},"pos":"noun"},{"en":"a hollow piece of light pastry that is filled with cream, jam, etc.","cn":"千层酥；奶油酥；泡芙","g":"[countable]","pos":"noun"},{"en":"a piece of writing or speech that praises somebody/something too much","cn":"吹捧的文章（或讲话）","g":"[countable]","lab":"North American English also","ex":{"en":"The press is full of puffs for his new movie.","cn":"媒体对他的新电影充满了吹捧。"},"pos":"noun"},{"en":"breath","cn":"呼吸；喘息","g":"[uncountable]","lab":"especially British English, informal，，","ex":{"en":"The hill was very steep and I soon ran out of puff.","cn":"山坡陡峭，我很快就气喘吁吁了。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吸，抽（香烟等）","en":"If someone puffs at a cigarette, cigar, or pipe, they smoke it.","ex":{"en":"He lit a cigar and puffed at it twice","cn":"他点了一支雪茄，吸了两口。"}},{"pos":"V-ERG 及物/不及物动词","cn":"吹；喷；吐","en":"If you puff smoke or moisture from your mouth or if it puffs from your mouth, you breathe it out.","ex":{"en":"Richard lit another cigarette and puffed smoke towards the ceiling","cn":"理查德又点了一支烟，朝着天花板喷云吐雾。"}},{"pos":"VERB 动词","cn":"（引擎、烟囱或锅炉）冒（烟或气）","en":"If an engine, chimney, or boiler puffs smoke or steam, clouds of smoke or steam come out of it.","ex":{"en":"As I completed my 26th lap the Porsche puffed blue smoke.","cn":"我跑了26圈时，保时捷车冒出了蓝烟。"}},{"pos":"N-COUNT 可数名词","cn":"（吹出的）一缕，一股","en":"A puff of something such as air or smoke is a small amount of it that is blown out from somewhere.","ex":{"en":"Wind caught the sudden puff of dust and blew it inland.","cn":"风猛地刮起一阵灰尘，将它吹往内陆。"}},{"pos":"VERB 动词","cn":"喘息；喘气","en":"If you are puffing, you are breathing loudly and quickly with your mouth open because you are out of breath after a lot of physical effort.","ex":{"en":"I know nothing about boxing, but I could see he was unfit, because he was puffing.","cn":"我对拳击一无所知，但我能看出他状态不佳，因为他在急促喘息。"}},{"pos":"N-COUNT 可数名词","cn":"吹捧；吹嘘","en":"A puff for something such as a book, film, product, or organization is something that is done or said in order to attract people's attention and tell them how good it is.","ex":{"en":"What is presented to the public as a critical evaluation is really an elaborate puff for him and his magazine.","cn":"公众所看到的评论界的好评实际上是对他和他的杂志的一种吹捧。"}},{"pos":"N-COUNT 可数名词","cn":"同poof","en":"A puff is the same as a poof ."},{"pos":"","cn":"","en":"相关词组：puff out puff up"}]},"examples":[{"en":"Any chance of success seemed to vanish in a puff of smoke (= to disappear quickly).","cn":"成功的机会犹如一缕青烟，瞬息即逝。"},{"en":"Take two puffs from the inhaler every four hours.","cn":"每隔四小时从吸药器中吸两口药。"}]},"purpose":{"media":{"uk":"media/uk/purpose__gb_1.mp3","us":"media/us/purpose__us_1.mp3"},"oxford":{"phon":"ˈpɜːpəs","pos":"noun","senses":[{"en":"the intention, aim or function of something; the thing that something is supposed to achieve","cn":"意图；目的；用途；目标","g":"[countable]","ex":{"en":"Our campaign's main purpose is to raise money.","cn":"我们这次活动的主要目的就是募款。"}},{"en":"what is needed in a particular situation","cn":"情势的需要","g":"[plural]","ex":{"en":"These gifts count as income for tax purposes.","cn":"这些礼物应属于纳税的收入。"}},{"en":"meaning that is important and valuable to you","cn":"重要意义；有价值的意义","g":"[countable, uncountable]","ex":{"en":"Volunteer work gives her life a sense of purpose.","cn":"做志愿工作使她的生活有了意义。"}},{"en":"the ability to plan something and work successfully to achieve it","cn":"意志；毅力；决心","g":"[uncountable]","ex":{"en":"He has enormous confidence and strength of purpose.","cn":"他信心十足，意志坚强。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"意义；用途","en":"The purpose of something is the reason for which it is made or done.","ex":{"en":"The purpose of the occasion was to raise money for medical supplies","cn":"那次活动是为筹集资金购买医药物资。"}},{"pos":"N-COUNT 可数名词","cn":"目标；目的","en":"Your purpose is the thing that you want to achieve.","ex":{"en":"They might well be prepared to do you harm in order to achieve their purpose","cn":"为达成自己的目的，他们说不定已经做好了伤害你的准备。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"意志；毅力；决心","en":"Purpose is the feeling of having a definite aim and of being determined to achieve it.","ex":{"en":"The teachers are enthusiastic and have a sense of purpose.","cn":"教师们很热情并且很有决心。"}},{"pos":"PHRASE 短语","cn":"实际上","en":"You use for all practical purposes or to all intents and purposes to suggest that a situation is not exactly as you describe it, but the effect is the same as if it were.","ex":{"en":"For all practical purposes the treaty has already ceased to exist","cn":"实际上协议已经不复存在。"}},{"pos":"PHRASE 短语","cn":"特意地；故意地；有意地","en":"If you do something on purpose, you do it intentionally.","ex":{"en":"Was it an accident or did David do it on purpose?","cn":"是意外还是戴维故意所为？"}}]},"examples":[{"en":"The whole idea of going was so that we could meet her new boyfriend.","cn":"我们去的唯一目的就是要见她的新男朋友。"},{"en":"For the purposes of this study, the three groups have been combined.","cn":"为了这项研究工作，三个小组业已合并。"}]},"purple":{"oxford":{"phon":"ˈpɜːpl","pos":"adjective","senses":[{"en":"having the colour of blue and red mixed together","cn":"紫色的","ex":{"en":"a purple flower/dress","cn":"紫色的花／连衣裙"}},{"en":"writing or a piece of writing that is too grand in style","cn":"华丽的文辞；雕琢的章句"},{"en":"the colour of blue and red mixed together","cn":"紫色","ex":{"en":"Her hair was dyed a bright shade of purple.","cn":"她的头发被染成了亮紫色。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"紫色","en":"Something that is purple is of a reddish-blue colour.","ex":{"en":"She wore purple and green silk.","cn":"她穿着紫绿相间的绸缎衣服。"}},{"pos":"ADJ 形容词","cn":"（文章）词藻华丽的，堆砌意象的","en":"Purple prose or a purple patch is a piece of writing that contains very elaborate language or images.","ex":{"en":"...passages of purple prose describing intense experiences.","cn":"一篇篇描述强烈感受的词藻华丽的散文"}},{"pos":"PHRASE 短语","cn":"（尤指运动员或球队）接连成功，好运不断","en":"If someone, especially a sports player or team, goes through a purple patch, they are very successful or lucky for a period.","ex":{"en":"In the last 10 minutes Tranmere struck a purple patch which culminated in their goal.","cn":"最后10分钟，特兰米尔队时来运转，终于收获了进球。"}}]},"media":{"uk":"media/uk/purple__gb_1.mp3","us":"media/us/purple__us_1.mp3"},"examples":[{"en":"She was dressed in purple.","cn":"她穿一身紫色衣裳。"},{"en":"His face was purple with rage.","cn":"他气得脸色发紫。"}]},"pulls":{"lemma":"pull","media":{"uk":"media/uk/pull__gb_1.mp3","us":"media/us/pull__us_1.mp3"}},"pungent":{"media":{"uk":"media/uk/pungent__gb_1.mp3","us":"media/us/pungent__us_1.mp3"},"oxford":{"phon":"ˈpʌndʒənt","pos":"adjective","senses":[{"en":"having a strong taste or smell","cn":"味道（或气味）强烈的；刺激性的","ex":{"en":"the pungent smell of burning rubber","cn":"烧橡胶的刺鼻气味"}},{"en":"direct and having a strong effect","cn":"说穿的；一语道破的；一针见血的","ex":{"en":"pungent criticism","cn":"一针见血的批评"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"味道强烈的；气味刺激的","en":"Something that is pungent has a strong, sharp smell or taste which is often so strong that it is unpleasant.","ex":{"en":"The more herbs you use, the more pungent the sauce will be.","cn":"用的香草越多，调味汁的味道就越浓烈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"一语道破的；一针见血的","en":"If you describe what someone has said or written as pungent, you approve of it because it has a direct and powerful effect and often criticizes something very cleverly.","ex":{"en":"He enjoyed the play's shrewd and pungent social analysis.","cn":"他喜欢剧中尖锐机敏、一针见血的社会分析。"}}]},"examples":[{"en":"the pungent smell of burning rubber","cn":"烧橡胶的刺鼻气味"},{"en":"pungent criticism","cn":"一针见血的批评"}]},"puzzles":{"lemma":"puzzle","media":{"img":["media/pic/puzzles_comp.jpg"]}},"purported":{"media":{"uk":"media/uk/purported__gb_1.mp3","us":"media/us/purported__us_1.mp3"},"oxford":{"phon":"pəˈpɔːtɪd","pos":"adjective","senses":[{"en":"that has been stated to have happened or to be true, when this might not be the case","cn":"据称的；传言的","ex":{"en":"the scene of the purported crime","cn":"传闻中的罪案发生地点"}}]},"examples":[{"en":"a letter purportedly written by Mozart","cn":"一封据传是莫扎特的亲笔信"},{"en":"the scene of the purported crime","cn":"传闻中的罪案发生地点"}]},"pub":{"oxford":{"phon":"pʌb","pos":"noun","senses":[{"en":"a building where people go to drink and meet their friends. Pubs serve alcoholic and other drinks, and often also food.","cn":"酒吧；酒馆","lab":"informal","ex":{"en":"We're all going to the pub after work.","cn":"下班后我们都要去酒吧。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"酒馆；酒吧","en":"A pub is a building where people can have drinks, especially alcoholic drinks, and talk to their friends. Many pubs also serve food. →see usage note at:","ex":{"en":"He was in the pub until closing time","cn":"他在酒吧里一直呆到打烊。"}}]},"media":{"img":["media/pic/buildings_comp.jpg","media/thumb/pub.jpg"],"uk":"media/uk/pub__gb_1.mp3","us":"media/us/pub__us_1.mp3"},"examples":[{"en":"They've gone down the pub for a drink.","cn":"他们下酒馆喝酒去了。"},{"en":"the landlord of the local pub","cn":"当地酒馆的老板"}]},"puffed":{"media":{"uk":"media/uk/puffed__gb_1.mp3","us":"media/us/puffed__us_1.mp3"},"oxford":{"phon":"pʌft","pos":"adjective","senses":[{"en":"breathing quickly and with difficulty because you have been taking a lot of physical exercise","cn":"气喘吁吁；上气不接下气","ex":{"en":"I get really puffed in the aerobics class.","cn":"我在健美操课上真的气喘吁吁。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肿的；肿胀的","en":"If a part of your body is puffed or puffed up, it is swollen because of an injury or because you are unwell.","ex":{"en":"His face was a little puffed","cn":"他的脸有些肿胀。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"气喘吁吁的；上气不接下气的","en":"If you are puffed or puffed out, you are breathing with difficulty because you have been using a lot of energy.","ex":{"en":"Do you get puffed out running up and down the stairs?","cn":"你要是在楼梯上跑上跑下的会不会喘不过气来？"}}]},"examples":[{"en":"I’m too puffed to dance anymore.","cn":"我累得上气不接下气﹐没法再跳舞了。"}],"base":"puff"},"pug":{"media":{"uk":"media/uk/pug__gb_1.mp3","us":"media/us/pug__us_1.mp3"},"oxford":{"phon":"pʌɡ","pos":"noun","senses":[{"en":"a small dog with short hair and a wide flat face with deep folds of skin","cn":"巴哥犬；哈巴狗"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"哈巴狗","en":"A pug is a small, fat, short-haired dog with a flat face."}]}},"pull":{"media":{"uk":"media/uk/pull__gb_1.mp3","us":"media/us/pull__us_1.mp3"},"oxford":{"phon":"pʊl","pos":"verb","senses":[{"en":"to take hold of something and use force in order to move it or try to move it towards yourself","cn":"拉；拽；扯；拖","g":"[intransitive, transitive]","sc":"move/remove something","ex":{"en":"You push and I'll pull.","cn":"你推，我拉。"}},{"en":"to remove something from a place by pulling","cn":"拔出；抽出","g":"[transitive]","sc":"move/remove something","ex":{"en":"If these weeds are not pulled, they will spread rapidly .","cn":"如果这些杂草不拔除，它们会迅速蔓延。"}},{"en":"to move somebody/something in a particular direction by pulling","cn":"（向某方向）拖，拉动","g":"[transitive]","sc":"move/remove something","ex":{"en":"Pull your chair nearer the table.","cn":"把你的椅子再往桌子拉近些。"}},{"en":"to hold or be attached to something and move it along behind you","cn":"将…拖在身后；拉；牵引","g":"[transitive]","sc":"move/remove something","ex":{"en":"In this area oxen are used to pull carts.","cn":"这个地区用牛拉车。"}},{"en":"to move your body or a part of your body in a particular direction, especially using force","cn":"扭转；移开；抽回","g":"[intransitive, transitive]","sc":"body","ex":{"en":"He tried to kiss her but she pulled away.","cn":"他想吻她，但她却扭开了身子。"}},{"en":"to open or close curtains, etc.","cn":"拉上；收拢","g":"[transitive]","sc":"curtains","ex":{"en":"Pull the curtains—it's dark outside.","cn":"外边天黑了，把窗帘拉上。"}},{"en":"to damage a muscle, etc. by using too much force","cn":"拉伤；扭伤；抻","g":"[transitive]","sc":"muscle","ex":{"en":"to pull a muscle/ligament/tendon","cn":"扭伤肌肉／肌腱／韧带"}},{"en":"to move a switch, etc. towards yourself or down in order to operate a machine or piece of equipment","cn":"扳动；拉；扣","g":"[transitive]","sc":"switch","ex":{"en":"Pull the lever to start the motor.","cn":"拉动手柄启动马达。"}},{"en":"to move or make a vehicle move to the side","cn":"（使车辆）转向，打斜","g":"[intransitive, transitive]","sc":"vehicle/engine","ex":{"en":"The wheel is pulling to the left.","cn":"方向盘正在向左打。"}},{"en":"to work hard and use a lot of power","cn":"吃力地运转","g":"[intransitive]","sc":"vehicle/engine","ex":{"en":"The old car pulled hard as we drove slowly up the hill.","cn":"老旧的汽车吃力地向前爬，把我们缓缓地拖上了山坡。"}},{"en":"to use oars to move a boat along","cn":"划；划动","g":"[intransitive, transitive]","sc":"boat","ex":{"en":"They pulled towards the shore.","cn":"他们向岸边划去。"}},{"en":"to attract the interest or support of somebody/something","cn":"吸引；博取","g":"[transitive]","sc":"crowd/support","ex":{"en":"They pulled in huge crowds on their latest tour.","cn":"最近巡回演出时，他们吸引了大批观众。"}},{"en":"to attract somebody sexually and get them to spend the evening with you","cn":"迷住；迷倒","g":"[transitive, intransitive]","lab":"British English, informal，，","sc":"attract sexually","ex":{"en":"He can still pull the girls.","cn":"他仍然能让姑娘们着迷。"}},{"en":"to succeed in playing a trick on somebody, committing a crime, etc.","cn":"（耍手腕）得逞；犯下（罪行）","g":"[transitive]","lab":"informal","sc":"trick/crime","ex":{"en":"He's pulling some sort of trick on you.","cn":"他在耍花招骗你呢。"}},{"en":"to cancel an event; to stop showing an advertisement, etc.","cn":"取消，撤销（活动、广告等）","g":"[transitive]","lab":"informal","sc":"cancel","ex":{"en":"The gig was pulled at the last moment.","cn":"音乐会临时取消了。"}},{"en":"an act of trying to make something move by taking hold of it and using force to bring it towards you","cn":"拉；拽；扯","g":"[countable]","sc":"trying to move something","ex":{"en":"I gave the door a sharp pull and it opened.","cn":"我猛地一拉，门开了。"},"pos":"noun"},{"en":"a strong physical force that makes something move in a particular direction","cn":"力；引力；磁力","g":"[singular]","sc":"physical force","ex":{"en":"the earth’s gravitational pull","cn":"地球的引力"},"pos":"noun"},{"en":"the fact of something attracting you or having a strong effect on you","cn":"吸引力；诱惑；影响","g":"[countable, usually singular]","sc":"attraction","ex":{"en":"The magnetic pull of the city was hard to resist.","cn":"都市的强大魅力难以抗拒。"},"pos":"noun"},{"en":"power and influence over other people","cn":"（对他人的）影响，影响力","g":"[uncountable]","lab":"informal","sc":"influence","ex":{"en":"people who have a lot of pull with the media","cn":"能左右传媒的人物"},"pos":"noun"},{"en":"an act of taking a deep breath of smoke from a cigarette, etc. or a deep drink of something","cn":"深吸；大口喝","g":"[countable]","sc":"on cigarette/drink","ex":{"en":"She took a long pull on her cigarette.","cn":"她深深地吸了口烟。"},"pos":"noun"},{"en":"a difficult walk up a steep hill","cn":"艰难攀登","g":"[countable, usually singular]","lab":"British English","sc":"walk up hill","ex":{"en":"It's a long pull up to the summit.","cn":"登上山顶要攀爬很久。"},"pos":"noun"},{"en":"an injury to a muscle caused by using too much force","cn":"拉伤；扭伤","g":"[countable]","sc":"muscle injury","pos":"noun"},{"en":"something such as a handle or rope that you use to pull something","cn":"拉手；拉绳；拉环","g":"[countable]","sc":"handle/rope","ex":{"en":"a bell/door pull","cn":"钟绳；门把手"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拉；拖；牵；扯","en":"When you pull something, you hold it firmly and use force in order to move it towards you or away from its previous position.","ex":{"en":"They have pulled out patients' teeth unnecessarily","cn":"他们毫无必要地拔掉了病人的牙。"}},{"pos":"VERB 动词","cn":"拿出；抽出","en":"When you pull an object from a bag, pocket, or cupboard, you put your hand in and bring the object out.","ex":{"en":"Jack pulled the slip of paper from his shirt pocket","cn":"杰克从衬衫口袋里抽出这张纸条。"}},{"pos":"VERB 动词","cn":"拉，拖（车或机械装置）","en":"When a vehicle, animal, or person pulls a cart or piece of machinery, they are attached to it or hold it, so that it moves along behind them when they move forward.","ex":{"en":"This is early-20th-century rural Sussex, when horses still pulled the plough","cn":"这是20世纪早期的萨塞克斯乡村，那时还是用马拉犁。"}},{"pos":"VERB 动词","cn":"挣脱；移开；抽出","en":"If you pull yourself or pull a part of your body in a particular direction, you move your body or a part of your body with effort or force.","ex":{"en":"Hughes pulled himself slowly to his feet","cn":"休斯慢慢站了起来。"}},{"pos":"VERB 动词","cn":"停车；停下","en":"When a driver or vehicle pulls to a stop or a halt, the vehicle stops.","ex":{"en":"He pulled to a stop behind a pickup truck","cn":"他在一辆皮卡货车后面停了下来。"}},{"pos":"VERB 动词","cn":"超前；领先","en":"In a race or contest, if you pull ahead of or pull away from an opponent, you gradually increase the amount by which you are ahead of them.","ex":{"en":"He pulled away, extending his lead to 15 seconds","cn":"他把领先优势逐渐扩大到了15秒。"}},{"pos":"VERB 动词","cn":"拆开；拆散","en":"If you pull something apart, you break or divide it into small pieces, often in order to put them back together again in a different way.","ex":{"en":"If I wanted to improve the car significantly I would have to pull it apart and start again.","cn":"如果想好好地改进这辆车，我将不得不把它拆开重装。"}},{"pos":"VERB 动词","cn":"拔出（枪或刀）威胁","en":"If someone pulls a gun or a knife on someone else, they take out a gun or knife and threaten the other person with it.","ex":{"en":"They had a fight. One of them pulled a gun on the other","cn":"他们打了起来。其中一人拔出枪指着另一个人。"}},{"pos":"VERB 动词","cn":"吸引，拉拢（人群、观众或选民）","en":"To pull crowds, viewers, or voters means to attract them.","ex":{"en":"The organisers have to employ performers to pull a crowd.","cn":"组织者不得不雇些演员来聚拢人气。"}},{"pos":"VERB 动词","cn":"吸引；影响","en":"If something pulls you or pulls your thoughts or feelings in a particular direction, it strongly attracts you or influences you in a particular way.","ex":{"en":"Joe felt there was little he could do to help Betty, and his heart was pulling him elsewhere.","cn":"乔感到帮不上贝蒂什么忙，他的心思在别的地方。"}},{"pos":"N-COUNT 可数名词","cn":"拉力；牵引力；吸力；引力","en":"A pull is a strong physical force which causes things to move in a particular direction.","ex":{"en":"...the pull of gravity.","cn":"重力的牵引"}},{"pos":"VERB 动词","cn":"支持；鼓励；为…打气","en":"If you are pulling for someone, you support and encourage them, especially in a competition.","ex":{"en":"We're all pulling for each other because we're desperate to win the Cup back","cn":"因为我们非常想赢回奖杯，所以一直在互相打气。"}},{"pos":"VERB 动词","cn":"扭伤；拉伤","en":"If you pull a muscle, you injure it by straining it.","ex":{"en":"Dave pulled a back muscle and could barely kick the ball","cn":"戴夫背部拉伤，几乎没法踢球。"}},{"pos":"VERB 动词","cn":"深吸（一口烟）","en":"If someone pulls on a cigarette, they take a deep breath with the cigarette in their mouth.","ex":{"en":"Jeff leaned back and pulled on his cigarette.","cn":"杰夫往后一靠，深深地吸了一口烟。"}},{"pos":"VERB 动词","cn":"（对某人）耍（花招），玩弄（手段）","en":"To pull a stunt or a trick on someone means to do something dramatic or silly in order to get their attention or trick them.","ex":{"en":"Everyone saw the stunt you pulled on me.","cn":"大家都看见了你对我耍的花招。"}},{"pos":"VERB 动词","cn":"吸引；引诱","en":"If someone pulls someone else, they succeed in attracting them sexually and in spending the rest of the evening or night with them."},{"pos":"PHRASE 短语","cn":"别打哈哈了","en":"You can say to someone 'Pull the other one' or 'Pull the other one, it's got bells on' to tell them that you do not believe what they have told you and you think they must be joking.","ex":{"en":"What! A big bloke like you, beaten by his wife! Pull the other one; it's got bells on.","cn":"什么！你这么一个大块头居然被他的妻子打了！别逗了。"}},{"pos":"","cn":"","en":"to pull oneself up by one's bootstraps→see: ; to pull a face→see: ; to pull a fast one→see: ; to pull someone's leg→see: ; to pull your punches→see: ; to pull rank→see: ; to pull your socks up→see: ; to pull out all the stops→see: ; to pull strings→see: ; to pull your weight→see: ; to pull the wool over someone's eyes→see: ;"},{"pos":"","cn":"","en":"相关词组：pull away pull back pull down pull in pull into pull off pull out pull over pull through pull together pull up pull up on"}]},"examples":[{"en":"The cyclists were together until the bend, when Tyler pulled ahead.","cn":"自行车选手们原本胶着在一起，直到转弯处泰勒才超前领先。"},{"en":"The old car pulled hard as we drove slowly up the hill.","cn":"老旧的汽车吃力地向前爬，把我们缓缓地拖上了山坡。"}]},"purposeful":{"media":{"uk":"media/uk/purposeful__gb_1.mp3","us":"media/us/purposeful__us_1.mp3"},"oxford":{"phon":"ˈpɜːpəsfl","pos":"adjective","senses":[{"en":"having a useful purpose; acting with a clear aim and with determination","cn":"目的明确的；有目的的；目标清晰而坚定的","ex":{"en":"Purposeful work is an important part of the regime for young offenders.","cn":"使从事有意义的劳动是管理少年犯的重要一环。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有明确目标的；坚决的","en":"If someone is purposeful, they show that they have a definite aim and a strong desire to achieve it.","ex":{"en":"She had a purposeful air, and it became evident that this was not a casual visit.","cn":"她一副无事不登三宝殿的神情，很明显，这不是一次随意造访。"}}]},"examples":[{"en":"Purposeful work is an important part of the regime for young offenders.","cn":"使从事有意义的劳动是管理少年犯的重要一环。"},{"en":"She looked purposeful and determined.","cn":"她看来胸有成竹、意志坚定。"}]},"public":{"media":{"uk":"media/uk/public__gb_1.mp3","us":"media/us/public__us_1.mp3"},"oxford":{"phon":"ˈpʌblɪk","pos":"adjective","senses":[{"en":"connected with ordinary people in society in general","cn":"平民的；大众的；公众的；百姓的","g":"[only before noun]","sc":"of ordinary people","ex":{"en":"The campaign is designed to increase public awareness of the issues.","cn":"这场运动旨在提高民众对这些问题的认识。"}},{"en":"provided, especially by the government, for the use of people in general","cn":"公共的；公立的","g":"[only before noun]","sc":"for everyone","ex":{"en":"a public education system","cn":"公共教育体系"}},{"en":"connected with the government and the services it provides","cn":"政府的；有关政府所提供服务的","g":"[only before noun]","lab":"British English","sc":"of government","ex":{"en":"public money/spending/funding","cn":"公款；公共开支；政府拨款"}},{"en":"known to people in general","cn":"人人皆知的；公开的","sc":"seen/heard by people","ex":{"en":"Details of the government report have not yet been made public.","cn":"政府报告的细节尚未公布。"}},{"en":"open to people in general; intended to be seen or heard by people in general","cn":"公之于众的；公开的","sc":"seen/heard by people","ex":{"en":"There is a ban on smoking in public places.","cn":"公共场所禁止吸烟。"}},{"en":"where there are a lot of people who can see and hear you","cn":"公开场合的；大庭广众的","sc":"place","ex":{"en":"Let's go somewhere a little less public.","cn":"咱们找一个僻静些的地方吧。"}},{"en":"ordinary people in society in general","cn":"平民；百姓；民众","sc":"ordinary people","ex":{"en":"The palace is now open to the public.","cn":"这座宫殿现在向大众开放了。"},"pos":"noun"},{"en":"a group of people who share a particular interest or who are involved in the same activity","cn":"志趣相同（或从事同一类活动）的群体","sc":"group of people","ex":{"en":"the theatre-going public","cn":"爱看戏的民众"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"平民；百姓；民众","en":"You can refer to people in general, or to all the people in a particular country or community, as the public .","ex":{"en":"Lauderdale House is now open to the public","cn":"劳德代尔艺术教育中心现已向公众开放。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"志趣相投（或从事同一类活动、具有共同特征）的群体","en":"You can refer to a set of people in a country who share a common interest, activity, or characteristic as a particular kind of public .","ex":{"en":"Market research showed that 93% of the viewing public wanted a hit film channel.","cn":"市场调查表明93%的观众希望有一个播放热门影片的频道。"}},{"pos":"ADJ 形容词","cn":"公众的；大众的","en":"Public means relating to all the people in a country or community.","ex":{"en":"The President is attempting to drum up public support for his economic program.","cn":"总统正竭力争取公众对他的经济计划予以支持。"}},{"pos":"ADJ 形容词","cn":"政府的；国家的；公共事务的","en":"Public means relating to the government or state, or things that are done for the people by the state.","ex":{"en":"The social services account for a substantial part of public spending.","cn":"社会福利事业占了一大部分的公共支出。"}},{"pos":"ADJ 形容词","cn":"公用的；公共的","en":"Public buildings and services are provided for everyone to use.","ex":{"en":"...the New York Public Library","cn":"纽约公立图书馆"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（场所）公共的，公开的","en":"A public place is one where people can go about freely and where you can easily be seen and heard.","ex":{"en":"...the heavily congested public areas of international airports","cn":"国际机场人潮涌动的公共场所"}},{"pos":"ADJ 形容词","cn":"（人物或生活）公众的","en":"If someone is a public figure or in public life, many people know who they are because they are often mentioned in newspapers and on television.","ex":{"en":"The Archbishop of Canterbury yesterday hit out at public figures who commit adultery","cn":"昨天坎特伯雷大主教严厉抨击了几位与人通奸的公众人物。"}},{"pos":"ADJ 形容词","cn":"（声明、事件等）公开的，公之于众的","en":"Public is used to describe statements, actions, and events that are made or done in such a way that any member of the public can see them or be aware of them.","ex":{"en":"The National Heritage Committee has conducted a public inquiry to find the answer","cn":"国家遗产委员会进行了公开调查以寻找答案。"}},{"pos":"ADJ 形容词","cn":"公之于众的；公开的；人人皆知的","en":"If a fact is made public or becomes public, it becomes known to everyone rather than being kept secret.","ex":{"en":"Blair wants any new evidence on IRA pub bombs made public","cn":"布莱尔希望将任何关于爱尔兰共和军制造的酒馆爆炸事件的新证据都公之于众。"}},{"pos":"PHRASE 短语","cn":"出现在公众视线中；为公众熟知的；广为人知","en":"If someone is in the public eye, many people know who they are, because they are famous or because they are often mentioned on television or in the newspapers.","ex":{"en":"One expects people in the public eye to conduct their personal lives with a certain decorum","cn":"人们期望公众人物的私生活能检点些。"}},{"pos":"PHRASE 短语","cn":"上市；公开出售股份","en":"If a company goes public, it starts selling its shares on the stock exchange.","ex":{"en":"In 1951 AC went public, having achieved an average annual profit of more than £50,000.","cn":"AC公司于1951年上市，当时平均年利润为5万多英镑。"}},{"pos":"PHRASE 短语","cn":"公开地；当众","en":"If you say or do something in public, you say or do it when a group of people are present.","ex":{"en":"Bylaws are to make it illegal to smoke in public.","cn":"地方法规将规定在公共场合抽烟为非法。"}},{"pos":"","cn":"","en":"to wash your dirty linen in public→see: ;"}]},"examples":[{"en":"Levels of waste from the factory may be a danger to public health.","cn":"工厂排出废弃物的含量可能危及大众的健康。"},{"en":"The campaign is designed to increase public awareness of the issues.","cn":"这场运动旨在提高民众对这些问题的认识。"}]},"publicly":{"oxford":{"phon":"ˈpʌblɪkli","pos":"adverb","senses":[{"en":"by the government","cn":"公共的；公立的","ex":{"en":"a publicly owned company","cn":"国有公司"}},{"en":"to people in general; for everyone to hear","cn":"人人皆知的；公开的","ex":{"en":"This information is not publicly available.","cn":"此信息不对外公开。"}},{"en":"for the use of people in general","cn":"人人皆知的；公开的","ex":{"en":"publicly accessible study centres","cn":"公共学习中心"}}]},"media":{"uk":"media/uk/publicly__gb_1.mp3","us":"media/us/publicly__us_1.mp3"},"examples":[{"en":"He later publicly apologized for his comments.","cn":"后来他对自己的言论作了公开道歉。"},{"en":"This information is not publicly available.","cn":"这个消息没有对外公开。"}]},"pursuit":{"media":{"uk":"media/uk/pursuit__gb_1.mp3","us":"media/us/pursuit__us_1.mp3"},"oxford":{"phon":"pəˈsjuːt","pos":"noun","senses":[{"en":"the act of looking for or trying to get something","cn":"追求；寻找","g":"[uncountable]","ex":{"en":"the pursuit of happiness/knowledge/profit","cn":"对幸福／知识／利润的追求"}},{"en":"the act of following or going after somebody, especially in order to catch them","cn":"追赶；追踪；追捕","g":"[uncountable]","ex":{"en":"We drove away with two police cars in pursuit (= following).","cn":"我们驾车离开，后面有两辆警车跟着追赶。"}},{"en":"something that you give your time and energy to, that you do as a hobby","cn":"事业；消遣；爱好","g":"[countable, usually plural]","ex":{"en":"outdoor/leisure/artistic pursuits","cn":"户外活动；休闲活动；艺术爱好"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"追求；寻求","en":"Your pursuit of something is your attempts at achieving it. If you do something in pursuit of a particular result, you do it in order to achieve that result.","ex":{"en":"...a young man whose relentless pursuit of excellence is conducted with single-minded determination.","cn":"一心一意、坚定不移地追求完美的年轻人"}},{"pos":"N-UNCOUNT 不可数名词","cn":"实行；贯彻；实施","en":"The pursuit of an activity, interest, or plan consists of all the things that you do when you are carrying it out.","ex":{"en":"The vigorous pursuit of policies is no guarantee of success.","cn":"坚决贯彻方针政策并不能保证成功。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"追赶；追逐；追捕","en":"Someone who is in pursuit of a person, vehicle, or animal is chasing them.","ex":{"en":"...a police officer who drove a patrol car at more than 120mph in pursuit of a motor cycle.","cn":"以超过每小时120英里的时速驾驶巡逻车追赶一辆摩托车的警官"}},{"pos":"N-SING 单数名词","cn":"（自行车赛和滑冰竞赛中的）追逐赛","en":"In cycling and skating, the pursuit is a race in which two competitors or teams start on opposite sides of a circular track and try to catch up with each other.","ex":{"en":"Moreau took gold in the five-kilometre individual pursuit competition.","cn":"莫罗在个人五公里追逐赛中获得金牌。"}},{"pos":"N-COUNT 可数名词","cn":"娱乐；爱好","en":"Your pursuits are your activities, usually activities that you enjoy when you are not working.","ex":{"en":"They both love outdoor pursuits","cn":"他们俩都喜欢户外活动。"}},{"pos":"PHRASE 短语","cn":"穷追不舍","en":"If you are in hot pursuit of someone, you are chasing after them with great determination.","ex":{"en":"I rushed through with Sue in hot pursuit.","cn":"我冲了过去，苏在后面穷追不舍。"}}]},"examples":[{"en":"We drove away with two police cars in pursuit (= following).","cn":"我们驾车离开，后面有两辆警车跟着追赶。"},{"en":"She travelled the world in pursuit of her dreams.","cn":"她走遍天下，追寻她的梦想。"}]},"publicity":{"media":{"uk":"media/uk/publicity__gb_1.mp3","us":"media/us/publicity__us_1.mp3"},"oxford":{"phon":"pʌbˈlɪsəti","pos":"noun","senses":[{"en":"the attention that is given to somebody/something by newspapers, television, etc.","cn":"（媒体的）关注，宣传，报道","ex":{"en":"good/bad/adverse publicity","cn":"有利的／不利的／反面的报道"}},{"en":"the business of attracting the attention of the public to something/somebody; the things that are done to attract attention","cn":"宣传业；广告宣传工作；传播工作","lab":"especially British English","ex":{"en":"She works in publicity.","cn":"她从事宣传工作。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"宣传；报道","en":"Publicity is information or actions that are intended to attract the public's attention to someone or something.","ex":{"en":"Much advance publicity was given to the talks","cn":"对于这次会谈有很多前期报道。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（媒体或公众的）关注","en":"When the news media and the public show a lot of interest in something, you can say that it is receiving publicity.","ex":{"en":"The case has generated enormous publicity in Brazil.","cn":"这个案件已经在巴西引起了极大的关注。"}}]},"examples":[{"en":"The band dressed up as the Beatles as a publicity stunt.","cn":"乐队扮作披头士乐队作为宣传噱头。"},{"en":"There has been a lot of advance publicity for her new film.","cn":"她的新电影尚未上映即大加宣传。"}]},"pulp":{"media":{"uk":"media/uk/pulp__gb_1.mp3","us":"media/us/pulp__us_1.mp3"},"oxford":{"phon":"pʌlp","pos":"noun","senses":[{"en":"a soft wet substance that is made especially by pressing hard on something","cn":"浆；浆状物","g":"[singular, uncountable]","ex":{"en":"Cook the fruit gently until it forms a pulp.","cn":"用文火把水果煮烂。"}},{"en":"a soft substance that is made by pressing hard on wood, cloth or other material that is mixed with water and chemicals, and that is then used to make paper","cn":"纸浆","g":"[uncountable]","ex":{"en":"paper/wood pulp","cn":"纸浆；木浆"}},{"en":"the soft part inside some fruit and vegetables","cn":"（瓜果等的）肉质部分，髓","g":"[uncountable]","ex":{"en":"Scoop out the pulp and serve it with sugar.","cn":"把果肉挖出来和糖一起食用。"}},{"en":"writing that is of poor quality but popular and often sensational","cn":"（常哗众取宠的）低俗流行作品","ex":{"en":"a writer of pulp fiction","cn":"低俗小说作家"}},{"en":"the soft, sensitive tissue in the inside of a tooth","cn":"牙髓","g":"[uncountable]","lab":"anatomy"},{"en":"to press hard on or beat something so that it becomes soft and wet","cn":"将…捣成浆","ex":{"en":"Unsold copies of the novel had to be pulped.","cn":"没卖出去的小说只好化成纸浆。"},"pos":"verb"},{"en":"a British pop group formed in 1981 and led by the singer Jarvis Cocker. The group's songs are often about the experiences and problems of ordinary life, and they include Do You Remember the First Time? (1994) and Common People (1995).","cn":"果浆乐团","pos":""}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"泥；酱；浆；糊","en":"If an object is pressed into a pulp, it is crushed or beaten until it is soft, smooth, and wet.","ex":{"en":"The olives are crushed to a pulp by stone rollers.","cn":"橄榄被石磙碾成了酱。"}},{"pos":"N-SING 单数名词","cn":"果肉；（蔬菜的）肉质部分","en":"In fruit or vegetables, the pulp is the soft part inside the skin.","ex":{"en":"Make maximum use of the whole fruit, including the pulp which is high in fibre.","cn":"水果的各个部分都要最大限度地利用，包括富含纤维的果肉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"木浆（造纸原料）","en":"Wood pulp is material made from crushed wood. It is used to make paper."},{"pos":"ADJ 形容词","cn":"（故事或小说）粗制滥造的，庸俗刺激的，耸人听闻的","en":"People refer to stories or novels as pulp fiction when they consider them to be of poor quality and intentionally shocking or sensational.","ex":{"en":"...lurid '50s pulp novels.","cn":"50年代粗制滥造的低俗小说"}},{"pos":"VERB 动词","cn":"把（纸张、蔬菜或水果）打成浆","en":"If paper, vegetables, or fruit are pulped, they are crushed into a smooth, wet paste.","ex":{"en":"Onions can be boiled and pulped to a puree.","cn":"洋葱可以煮一下打成糊。"}},{"pos":"VERB 动词","cn":"把（纸币或文件）化成浆","en":"If money or documents are pulped, they are destroyed. This is done to stop the money being used or to stop the documents being seen by the public.","ex":{"en":"25 million pounds worth of five pound notes have been pulped because the designers made a mistake.","cn":"因为设计者们犯了一个错误，致使价值2,500万英镑的5英镑纸钞被化成纸浆。"}},{"pos":"PHRASE 短语","cn":"把…打得稀巴烂；把…打成重伤","en":"If someone is beaten to a pulp or beaten to pulp, they are hit repeatedly until they are very badly injured.","ex":{"en":"I tried to talk myself out of a fight and got beaten to a pulp instead by three other boys.","cn":"我尽量克制住自己不要打架，却被另外3个男孩打成了重伤。"}}]},"examples":[{"en":"Unsold copies of the novel had to be pulped.","cn":"没卖出去的小说只好化成纸浆。"},{"en":"Cook the fruit slowly until soft and pulpy.","cn":"把水果慢慢地煮成软糊状。"}]},"puppet":{"media":{"uk":"media/uk/puppet__gb_1.mp3","us":"media/us/puppet__us_1.mp3","img":["media/ldoce/img/puppet.jpg"]},"oxford":{"phon":"ˈpʌpɪt","pos":"noun","senses":[{"en":"a model of a person or an animal that can be made to move, for example by pulling strings attached to parts of its body or by putting your hand inside it. A puppet with strings is also called a marionette.","cn":"玩偶；木偶","ex":{"en":"a hand puppet","cn":"手偶"}},{"en":"a person or group whose actions are controlled by another","cn":"傀儡","lab":"usually disapproving","ex":{"en":"The occupying forces set up a puppet government.","cn":"占领军建立了一个傀儡政府。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"木偶","en":"A puppet is a doll that you can move, either by pulling strings which are attached to it or by putting your hand inside its body and moving your fingers."},{"pos":"N-COUNT 可数名词","cn":"傀儡；受人操纵者","en":"You can refer to a person or country as a puppet when you mean that their actions are controlled by a more powerful person or government, even though they may appear to be independent.","ex":{"en":"When the invasion occurred he ruled as a puppet of the occupiers","cn":"外敌入侵时，他作为占领者的傀儡行使统治。"}}]},"examples":[{"en":"The occupying forces set up a puppet government.","cn":"占领军建立了一个傀儡政府。"},{"en":"a hand puppet","cn":"手套式木偶"}]},"pure":{"oxford":{"phon":"pjʊə(r)","pos":"adjective","senses":[{"en":"not mixed with anything else; with nothing added","cn":"纯的；纯净的；纯粹的","g":"[usually before noun]","sc":"not mixed","ex":{"en":"pure gold","cn":"纯金"}},{"en":"clean and not containing any harmful substances","cn":"干净的；不含有害物质的","sc":"clean","ex":{"en":"a bottle of pure water","cn":"一瓶纯净水"}},{"en":"complete and total","cn":"完全的；纯粹的","g":"[only before noun]","sc":"complete","ex":{"en":"They met by pure chance.","cn":"他们相遇纯属偶然。"}},{"en":"very clear; perfect","cn":"清晰的；纯正的","sc":"colour/sound/light","ex":{"en":"beaches of pure white sand","cn":"洁白的沙滩"}},{"en":"without evil thoughts or actions, especially sexual ones; morally good","cn":"纯真的；无邪的；贞洁的；正派的","lab":"literary","sc":"morally good","ex":{"en":"to lead a pure life","cn":"过纯洁的生活"}},{"en":"about increasing knowledge of the subject rather than using knowledge in practical ways","cn":"纯理论的；非应用的","g":"[only before noun]","sc":"subject you study","ex":{"en":"pure mathematics","cn":"纯粹数学"}},{"en":"not mixed with any other type of animal or plant","cn":"血统纯的；纯种的","sc":"animal/plant","ex":{"en":"These cattle are one of the purest breeds in Britain.","cn":"这些牛是英国最纯的品种之一。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"纯粹的；不掺杂的","en":"A pure substance is not mixed with anything else.","ex":{"en":"...a carton of pure orange juice.","cn":"一盒纯橙汁"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"纯净的；洁净的；不含有害物质的","en":"Something that is pure is clean and does not contain any harmful substances.","ex":{"en":"In remote regions, the air is pure and the crops are free of poisonous insecticides.","cn":"在偏远地区，空气很纯净，庄稼也不施用有毒的杀虫剂。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"纯净的；纯正的；完美的","en":"If you describe something such as a colour, a sound, or a type of light as pure, you mean that it is very clear and represents a perfect example of its type.","ex":{"en":"...flowers in a whole range of blues with the occasional pure white.","cn":"各种深深浅浅的蓝色花朵，偶尔有纯白色花朵点缀其间"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"纯粹的；标准的；真正的","en":"If you describe a form of art or a philosophy as pure, you mean that it is produced or practised according to a standard or form that is expected of it.","ex":{"en":"Nicholson never swerved from his aim of making pure and simple art.","cn":"尼科尔森始终坚持创作纯粹简单的艺术，从未动摇过。"}},{"pos":"ADJ 形容词","cn":"（科学或研究）纯理论的，抽象的","en":"Pure science or pure research is concerned only with theory and not with how this theory can be used in practical ways.","ex":{"en":"Physics isn't just about pure science with no immediate applications","cn":"物理学并非只是一门不能直接运用的纯科学。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"完全的；十足的","en":"Pure means complete and total.","ex":{"en":"The old man turned to give her a look of pure surprise","cn":"老人转身十分惊奇地看了她一眼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"纯洁的；清白的；贞洁的","en":"A person, especially a woman, who is described as pure is considered to be morally good, especially because they have no sexual experience or sexual thoughts.","ex":{"en":"She was baptized and she was pure and clean of sin.","cn":"接受了洗礼的她纯洁无瑕。"}},{"pos":"PHRASE 短语","cn":"完全的；纯粹的；不折不扣的","en":"You use pure and simple to emphasize that the thing you are mentioning is the only thing that is involved or that should be considered.","ex":{"en":"It's blackmail, pure and simple.","cn":"这纯粹是敲诈。"}}]},"media":{"uk":"media/uk/pure__gb_1.mp3","us":"media/us/pure__us_1.mp3"},"examples":[{"en":"One movie is classified as pure art, the other as entertainment.","cn":"一部电影被列为纯艺术片，另一部被列为娱乐片。"},{"en":"These shirts are 100% pure cotton.","cn":"这些衬衫是 100% 的纯棉。"}]},"publishing":{"oxford":{"phon":"ˈpʌblɪʃɪŋ","pos":"noun","senses":[{"en":"the profession or business of preparing and printing books, magazines, CD-ROMs, etc. and selling or making them available to the public","cn":"出版（业）；发行（业）","ex":{"en":"a job in publishing","cn":"出版界的工作"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"出版业","en":"Publishing is the profession of publishing books.","ex":{"en":"I had a very high-powered job in publishing.","cn":"我曾在出版业担任要职。"}}]},"media":{"uk":"media/uk/publishing__gb_1.mp3","us":"media/us/publishing__us_1.mp3"},"examples":[{"en":"a publishing house (= company)","cn":"出版社"},{"en":"Tony wants to get a job in publishing.","cn":"托尼想在出版界找一份工作。"}],"base":"publish"},"pubs":{"lemma":"pub"},"pump":{"oxford":{"phon":"pʌmp","pos":"verb","senses":[{"en":"to make water, air, gas, etc. flow in a particular direction by using a pump or something that works like a pump","cn":"用泵（或泵样器官等）输送","g":"[transitive]","ex":{"en":"The engine is used for pumping water out of the mine.","cn":"这台发动机是用来从矿井中抽水的。"}},{"en":"to flow in a particular direction as if it is being forced by a pump","cn":"涌出；涌流；奔流","g":"[intransitive]","ex":{"en":"Blood was pumping out of his wound.","cn":"血从他的伤口喷出。"}},{"en":"to move something quickly up and down or in and out","cn":"上下（或内外）快速摇动；急速摇晃","g":"[transitive]","ex":{"en":"He kept pumping my hand up and down.","cn":"他不停地摇动着我的手。"}},{"en":"to move quickly up and down or in and out","cn":"快速上下（或内外）运动","g":"[intransitive]","ex":{"en":"She sprinted for the line, legs pumping.","cn":"她双腿紧蹬，奔向终点线。"}},{"en":"to try to get information from somebody by asking them a lot of questions","cn":"盘问；追问；一再探问","g":"[transitive]","lab":"informal","ex":{"en":"See if you can pump him for more details.","cn":"看你能不能向他再探问出些细节来。"}},{"en":"a machine that is used to force liquid, gas or air into or out of something","cn":"抽水机；泵；打气筒","lab":"British English","ex":{"en":"a petrol pump","cn":"汽油泵"},"pos":"noun"},{"en":"a light simple sports shoe made of canvas (= strong cotton cloth) with a rubber sole","cn":"橡胶底帆布鞋；体操鞋","lab":"old-fashioned","pos":"noun"},{"en":"a woman’s formal shoe that is plain and does not cover the top part of the foot","cn":"船鞋，无带低帮女鞋，无带半高跟女鞋（正式场合穿的朴素女鞋）","lab":"especially North American English","pos":"noun"},{"en":"a woman’s light, soft flat shoe worn for dancing or exercise; a similar style of shoe worn as a fashion item","cn":"轻软舞鞋，休闲女鞋（女子跳舞、运动时穿或用作时装）","lab":"British English","ex":{"en":"ballet pumps","cn":"芭蕾舞鞋"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"泵；抽水机；打气筒","en":"A pump is a machine or device that is used to force a liquid or gas to flow in a particular direction.","ex":{"en":"...pumps that circulate the fuel around in the engine","cn":"使燃料在发动机内循环的泵"}},{"pos":"VERB 动词","cn":"抽吸；抽运；泵送","en":"To pump a liquid or gas in a particular direction means to force it to flow in that direction using a pump.","ex":{"en":"It's not enough to get rid of raw sewage by pumping it out to sea","cn":"将未经处理的污水排入海中了事是不够的。"}},{"pos":"N-COUNT 可数名词","cn":"（汽油）加油泵","en":"A petrol or gas pump is a machine with a tube attached to it that you use to fill a car with petrol.","ex":{"en":"There are already long queues of vehicles at petrol pumps.","cn":"加油泵边车辆已经排起了长队。"}},{"pos":"VERB 动词","cn":"洗（胃）","en":"If someone has their stomach pumped, doctors remove the contents of their stomach, for example because they have swallowed poison or drugs.","ex":{"en":"She was released from hospital yesterday after having her stomach pumped.","cn":"洗胃之后，她昨天出了院。"}},{"pos":"VERB 动词","cn":"大量投入；大量注入","en":"If you pump money or other resources into something such as a project or an industry, you invest a lot of money or resources in it.","ex":{"en":"The Government needs to pump more money into community care.","cn":"政府需要将更多资金投入到社区护理这一块。"}},{"pos":"VERB 动词","cn":"不停地追问","en":"If you pump someone about something, you keep asking them questions in order to get information.","ex":{"en":"He ran in every five minutes to pump me about the case","cn":"他每隔五分钟就跑来追问我这件事。"}},{"pos":"VERB 动词","cn":"接连发射；快速连射","en":"To pump bullets into someone means to fire a lot of bullets into them very quickly.","ex":{"en":"A gunman burst in and pumped five bullets into her head.","cn":"一个持枪歹徒闯进来，朝她的脑袋连射5枪。"}},{"pos":"N-COUNT 可数名词","cn":"（运动或休闲时穿的）橡胶底帆布鞋","en":"Pumps are canvas shoes with flat rubber soles which people wear for sports and leisure."},{"pos":"N-COUNT 可数名词","cn":"（通常皮制的）女式浅口鞋","en":"Pumps are women's shoes that do not cover the top part of the foot and are usually made of plain leather."},{"pos":"PHRASE 短语","cn":"刺激（经济等的）发展","en":"To prime the pump means to do something to encourage the success or growth of something, especially the economy.","ex":{"en":"...the use of tax money to prime the pump of the state's economy.","cn":"用税收收入来刺激该国经济发展"}},{"pos":"","cn":"","en":"to pump iron→see: ;"},{"pos":"","cn":"","en":"相关词组：pump out pump up"}]},"media":{"img":["media/pic/cycles_comp.jpg","media/thumb/pump.jpg"],"uk":"media/uk/pump__gb_1.mp3","us":"media/us/pump__us_1.mp3"},"examples":[{"en":"It's difficult to pump facts and figures into tired students.","cn":"把事实和数字硬灌输给疲惫的学生太难了。"},{"en":"Our cars pump out thousands of tonnes of poisonous fumes every year.","cn":"我们的汽车每年排放出数千吨的有毒尾气。"}]},"purchases":{"lemma":"purchase"},"pushing":{"lemma":"push","media":{"uk":"media/ldoce/hwd/bre/6/brelasdepushing.mp3","us":"media/ldoce/hwd/ame/1/laadpushing.mp3"}},"pulled":{"lemma":"pull"},"puts":{"lemma":"put"},"pummelled":{"oxford":{"phon":"ˈpʌml","pos":"verb","senses":[{"en":"to keep hitting sb/sth hard, especially with your fists (= tightly closed hands)","cn":"连续猛击；反复拳打；捶打"}]}},"published":{"lemma":"publish"},"purchasers":{"oxford":{"phon":"ˈpɜːtʃəsə(r)","pos":"noun","senses":[{"en":"a person who buys sth","cn":"购买人；采购人员；买主"}]}},"pulling":{"lemma":"pull"},"purposes":{"lemma":"purpose"},"purists":{"oxford":{"phon":"ˈpjʊərɪst","pos":"noun","senses":[{"en":"a person who thinks things should be done in the traditional way and who has strong opinions on what is correct in language, art, etc. （","cn":"语言、艺术等方面的）纯粹主义者，正统主义者"}]}},"pursuits":{"lemma":"pursuit"},"publicize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"宣传；宣扬；推广","en":"If you publicize a fact or event, you make it widely known to the public.","ex":{"en":"The author appeared on television to publicize her latest book","cn":"那位作家上电视宣传她的新书。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell people about a product or service and try to persuade them to buy it, for example in a newspaper, television, or Internet advertisement","cn":""},{"en":"to try to increase the sales or popularity of a product or event, for example by selling it at a lower price or talking about it on television","cn":""},{"en":"to try to sell a product or service by deciding which type of people are likely to buy it and by making it interesting to them","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you publicize something, you let the whole world know about it. The president might hold a press conference to publicize a new policy, or you might use Facebook to publicize your new relationship status."}]},"collocations":{"phrases":["ADV. well | widely","VERB + PUBLICIZE help (to)","PHRASES little publicized, highly/much publicized her highly publicized affair with a leading politician"]},"media":{"uk":"media/ldoce/hwd/bre/1/publicize0205.mp3","us":"media/ldoce/hwd/ame/f/publicize.mp3"},"examples":[{"en":"He was in London publicizing his new biography of Kennedy.","cn":"他在伦敦推销他新出版的肯尼迪传。"},{"en":"They flew to Europe to publicize the plight of the refugees.","cn":"他们飞往欧洲报道难民的惨状。"}],"oxford":{"phon":"ˈpʌblɪsaɪz","pos":"verb","senses":[{"en":"to make something known to the public; to advertise something","cn":"宣传；推广；宣扬；传播","ex":{"en":"They flew to Europe to publicize the plight of the refugees.","cn":"他们飞往欧洲报道难民的惨状。"}}]}},"pus":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"脓；脓液","en":"Pus is a thick yellowish liquid that forms in wounds when they are infected."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thick yellowish liquid produced in an infected part of your body","cn":"脓"}]},"collocations":{"phrases":["ADJ. yellow","VERB + PUS discharge, ooze The wound had not healed properly and was oozing pus.","PUS + VERB gather | ooze (out)","PUS + NOUN cell"]},"media":{"uk":"media/ldoce/hwd/bre/9/pus0205.mp3","us":"media/ldoce/hwd/ame/c/pus.mp3"},"examples":[{"en":"a wound oozing pus","cn":"化脓的伤口"}],"oxford":{"phon":"pʌs","pos":"noun","senses":[{"en":"a thick yellow or green liquid that is produced in a wound as a result of an infection","cn":"脓","ex":{"en":"The wound had not healed properly and was oozing pus.","cn":"伤口还未真正痊愈，正在流脓。"}}]}},"pushchair":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"婴儿手推车；婴儿车","en":"A pushchair is a small chair on wheels, in which a baby or small child can sit and be wheeled around."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small seat on wheels, in which a young child sits and is pushed along","cn":"婴儿手推车﹐婴儿车"}]},"collocations":{"phrases":["ADJ. collapsible, folding","VERB + PUSHCHAIR push (along), wheel (along) | collapse, fold (up)","PREP. in a/the ~"]},"media":{"img":["media/ldoce/img/stroller.jpg","media/pic/pushchair_comp.jpg"],"uk":"media/ldoce/hwd/bre/8/pushchair0205.mp3","us":"media/ldoce/hwd/ame/9/ld41pushchair.mp3"},"oxford":{"phon":"ˈpʊʃtʃeə(r)","pos":"noun","senses":[{"en":"a small folding seat on wheels in which a small child sits and is pushed along","cn":"折叠式幼儿车；童车"}]}},"publication":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"出版；发行","en":"The publication of a book or magazine is the act of printing it and sending it to shops to be sold.","ex":{"en":"The guide is being translated into several languages for publication near Christmas","cn":"该手册正被译成数种语言，将在临近圣诞节时出版。"}},{"pos":"N-COUNT 可数名词","cn":"出版物；发行物","en":"A publication is a book or magazine that has been published.","ex":{"en":"They have started legal proceedings against two publications which spoke of an affair.","cn":"他们开始对两本提及一桩婚外情的出版物提起法律诉讼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"公布；发布","en":"The publication of something such as information is the act of making it known to the public, for example by informing journalists or by publishing a government document.","ex":{"en":"A spokesman said: 'We have no comment regarding the publication of these photographs.'","cn":"一位发言人说，“对于这些照片的公之于众，我们不予置评。”"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of printing a book, magazine etc and offering it for sale","cn":"出版"},{"en":"a book, magazine etc","cn":"书﹔刊物﹔著作﹔出版物"},{"en":"when information is printed in a book, magazine etc so that the public can read it","cn":"发表﹐公布"}]},"vocab":{"pos":"n","senses":[{"en":"A publication is something made to communicate with the public. Publications are usually printed on paper (like magazines and books), but online publications are delivered via the Internet."}]},"collocations":{"phrases":["VERB + PUBLICATION begin | cease, stop | prepare sth for | be due/scheduled for The book is scheduled for publication in the autumn. | accep","PUBLICATION + VERB be due/scheduled The publication of her memoirs is scheduled for the autumn.","PUBLICATION + NOUN date","PHRASES the date/time of publication 2 book, magazine, etc.","ADJ. new, recent | forthcoming | leading, major | sister &lsquo;This Week&rsquo;'s German sister publication, &lsquo;Diese Woche&rsquo;, wen","PUBLICATION + NOUN publications catalogue/list","PREP. ~ about specialist publications about bees | ~ on She has several publications to her name on local history."]},"media":{"uk":"media/ldoce/hwd/bre/3/publication0205.mp3","us":"media/ldoce/hwd/ame/4/publication.mp3"},"examples":[{"en":"The newspaper continues to defend its publication of the photographs.","cn":"这家报纸继续为刊登这些照片辩护。"},{"en":"a delay in the publication of the exam results","cn":"考试成绩的延期公布"}],"oxford":{"phon":"ˌpʌblɪˈkeɪʃn","pos":"noun","senses":[{"en":"the act of printing a book, a magazine, etc. and making it available to the public; a book, a magazine, etc. that has been published","cn":"（书刊等的）出版，发行；出版物","g":"[uncountable, countable]","ex":{"en":"specialist publications","cn":"专业出版物"}},{"en":"the act of printing something in a newspaper, report, etc. so that the public knows about it","cn":"发表；刊登；公布","g":"[uncountable]","ex":{"en":"The Home Secretary attempted to get an injunction to prevent publication, but was unsuccessful.","cn":"内政大臣试图获得禁止出版的禁令，但没有成功。"}}]}},"pullover":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"套头毛衣","en":"A pullover is a piece of woollen clothing that covers the upper part of your body and your arms. You put it on by pulling it over your head."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of woollen clothing without buttons that you wear on the top half of your body","cn":"套头毛衣"}]},"collocations":{"phrases":["ADJ. woollen, woolly | sleeveless | knitted She was wearing a knitted pullover. | Fair Isle","VERB + PULLOVER knit •"]},"media":{"uk":"media/ldoce/hwd/bre/d/pullover0205.mp3","us":"media/ldoce/hwd/ame/3/pullover.mp3"},"oxford":{"phon":"ˈpʊləʊvə(r)","pos":"noun","senses":[{"en":"a knitted piece of clothing made of wool or cotton for the upper part of the body, with long sleeves and no buttons","cn":"套头衫；套头毛衣","ex":{"en":"She was wearing a knitted pullover.","cn":"她穿着一件针织套头毛衣。"}}]}},"pulse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脉搏；脉动","en":"Your pulse is the regular beating of blood through your body, which you can feel when you touch particular parts of your body, especially your wrist.","ex":{"en":"Mahoney's pulse was racing, and he felt confused.","cn":"马奥尼脉搏跳得很快，他感到很慌乱。"}},{"pos":"N-COUNT 可数名词","cn":"拍子；节奏；（常指）鼓点","en":"In music, a pulse is a regular beat, which is often produced by a drum.","ex":{"en":"...the repetitive pulse of the music.","cn":"音乐中重复的鼓点"}},{"pos":"N-COUNT 可数名词","cn":"脉冲","en":"A pulse of electrical current, light, or sound is a temporary increase in its level.","ex":{"en":"The switch works by passing a pulse of current between the tip and the surface.","cn":"那个开关通过在末梢和表面之间传输电流脉冲工作。"}},{"pos":"N-SING 单数名词","cn":"意向；心态","en":"If you refer to the pulse of a group in society, you mean the ideas, opinions, or feelings they have at a particular time.","ex":{"en":"The White House insists that the president is in touch with the pulse of the black community.","cn":"白宫坚持称总统是了解黑人群体的心声的。"}},{"pos":"VERB 动词","cn":"（有节奏地）跳动，搏动，震动","en":"If something pulses, it moves, appears, or makes a sound with a strong regular rhythm.","ex":{"en":"His temples pulsed a little, threatening a headache","cn":"他的太阳穴跳了一会，像是头痛要发作了。"}},{"pos":"N-PLURAL 复数名词","cn":"（可食用的）豆子","en":"Some seeds which can be cooked and eaten are called pulses, for example peas, beans, and lentils."},{"pos":"PHRASE 短语","cn":"保持消息灵通","en":"If you have your finger on the pulse of something, you know all the latest opinions or developments concerning it.","ex":{"en":"He claims to have his finger on the pulse of the industry","cn":"他声称该对行业了如指掌。"}},{"pos":"PHRASE 短语","cn":"测脉搏；把脉","en":"When someone takes your pulse or feels your pulse, they find out how quickly your heart is beating by feeling the pulse in your wrist."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is knowledgeable knows a lot of different facts, especially about a particular subject or activity","cn":""},{"en":"knowing a lot about what is happening, especially about what is happening in the world","cn":""},{"en":"to know a lot about a particular subject or about various subjects, so that you are usually able to answer anything that people ask you","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n","senses":[{"en":"The word pulse has many shades of meaning, but most of them involve something characterized by short, rhythmic bursts. If you’re angry, the muscles in your jaw might pulse — meaning they contract quickly in short bursts."}]},"collocations":{"phrases":["ADJ. fast, racing, rapid | slow | strong | faint, weak","VERB + PULSE check, feel, take Last time I took my pulse, it was a bit fast. | check for, feel for She reached in through the driver's broke","PULSE + VERB beat | quicken, race She felt her pulse quicken as she recognized the voice. | slow","PULSE + NOUN rate My at-rest pulse rate is usually about 80 beats per minute."]},"media":{"uk":"media/ldoce/hwd/bre/8/pulse_n0205.mp3","us":"media/ldoce/hwd/ame/1/pulse1.mp3"},"examples":[{"en":"The doctor took/felt my pulse.","cn":"医生给我量了脉搏/把了脉。"},{"en":"A vein pulsed in his temple.","cn":"他太阳穴上的静脉在搏动。"}],"oxford":{"phon":"pʌls","pos":"noun","senses":[{"en":"the regular beat of the heart as it sends blood around the body, that can be felt in different places, especially on the inside part of the wrist; the number of times the heart beats in a minute","cn":"脉搏；脉率","g":"[usually singular]","ex":{"en":"a strong/weak pulse","cn":"强／弱脉搏"}},{"en":"a strong regular beat in music","cn":"强劲的音乐节拍","ex":{"en":"the throbbing pulse of the drums","cn":"阵阵强劲的鼓点"}},{"en":"a single short increase in the amount of light, sound or electricity produced by a machine, etc.","cn":"脉冲","ex":{"en":"pulse waves","cn":"脉冲波"}},{"en":"the seeds of some plants that are eaten as food, such as peas and lentils","cn":"豆果果实；荚果；豆子","g":"[plural]","ex":{"en":"Pulses are a good source of protein.","cn":"豆类是蛋白质的良好来源。"}},{"en":"to move, beat or flow with strong regular movements or sounds","cn":"搏动；跳动；震动","g":"[intransitive]","ex":{"en":"A vein pulsed in his temple.","cn":"他太阳穴上的静脉在搏动。"},"pos":"verb"},{"en":"to be full of a feeling such as excitement or energy","cn":"洋溢着；充满（激情等）","g":"[intransitive]","ex":{"en":"The auditorium pulsed with excitement.","cn":"礼堂里洋溢着热烈的气氛。"},"pos":"verb"}]}},"pursue":{"collins":{"senses":[{"pos":"VERB 动词","cn":"实行；执行；贯彻","en":"If you pursue an activity, interest, or plan, you carry it out or follow it.","ex":{"en":"It became harder for women married to diplomats to pursue their own interests","cn":"与外交官结婚的女性要追求自己的爱好就变得更加困难了。"}},{"pos":"VERB 动词","cn":"寻求；追求","en":"If you pursue a particular aim or result, you make efforts to achieve it, often over a long period of time.","ex":{"en":"The implication seems to be that it is impossible to pursue economic reform and democracy simultaneously","cn":"言外之意似乎是经济改革和民主化进程是不可能同时进行的。"}},{"pos":"VERB 动词","cn":"追查；追问；追究","en":"If you pursue a particular topic, you try to find out more about it by asking questions.","ex":{"en":"If your original request is denied, don't be afraid to pursue the matter.","cn":"如果你最初的请求遭到拒绝，不要害怕，要继续追问下去。"}},{"pos":"VERB 动词","cn":"追赶；追逐；追捕","en":"If you pursue a person, vehicle, or animal, you follow them, usually in order to catch them.","ex":{"en":"She pursued the man who had stolen a woman's bag.","cn":"她追赶那个偷了一个妇女提包的男人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk, drive etc behind or after someone, for example in order to see where they are going","cn":""},{"en":"to quickly run or drive after someone or something in order to catch them when they are trying to escape","cn":""},{"en":"to quickly follow someone or something in order to stop them or talk to them","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Use the verb pursue when you're chasing after someone — the way that paparazzi pursue a celebrity."}]},"collocations":{"phrases":["ADV. further, still | actively, energetically, vigorously | doggedly He was still doggedly pursuing his studies. | relentlessly | effectivel","VERB + PURSUE decide to We have decided not to pursue the matter further. | intend to, want to, wish to deciding on which career you wish to","PHRASES the ability/freedom to pursue sth the freedom to pursue her own interests | be not worth pursuing I decided the matter was not worth","ADV. relentlessly He pursued her relentlessly, refusing to take &lsquo;no&rsquo; for an answer.","PHRASES closely/hotly pursued by sb He ran past, hotly pursued by two policemen."]},"media":{"uk":"media/ldoce/hwd/bre/6/pursue0205.mp3","us":"media/ldoce/hwd/ame/5/pursue.mp3"},"examples":[{"en":"to pursue a goal/an aim/an objective","cn":"追求目标；贯彻宗旨；实现目标"},{"en":"She left the theatre, hotly pursued by the press.","cn":"她离开剧场，被记者穷追不舍。"}],"oxford":{"phon":"pəˈsjuː","pos":"verb","senses":[{"en":"to do something or try to achieve something over a period of time","cn":"追求；致力于；执行；贯彻","ex":{"en":"to pursue a goal","cn":"追求目标"}},{"en":"to continue to discuss, find out about or be involved in something","cn":"继续探讨（或追究、从事）","ex":{"en":"to pursue an agenda/a strategy/a claim","cn":"继续推进议程／战略／主张"}},{"en":"to follow or go after somebody/something, especially in order to catch them","cn":"追赶；追踪；追捕","ex":{"en":"She left the theatre, hotly pursued by the press.","cn":"她离开剧场，被记者穷追不舍。"}}]}},"putting":{"lemma":"put","media":{"uk":"media/ldoce/hwd/bre/6/putt0205.mp3","us":"media/ldoce/hwd/ame/0/putt.mp3"}},"punch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"用拳猛击（或攻击）","en":"If you punch someone or something, you hit them hard with your fist.","ex":{"en":"After punching him on the chin she wound up hitting him over the head","cn":"她先挥拳打他的下巴，然后又打他的脑袋。"}},{"pos":"VERB 动词","cn":"挥舞拳头","en":"If you punch the air, you put one or both of your fists forcefully above your shoulders as a gesture of delight or victory.","ex":{"en":"At the end, Graf punched the air in delight, a huge grin on her face.","cn":"最后，格拉夫高兴得挥动着拳头，脸上笑开了花。"}},{"pos":"VERB 动词","cn":"按（键等）；压（按钮等）","en":"If you punch something such as the buttons on a keyboard, you touch them in order to store information on a machine such as a computer or to give the machine a command to do something.","ex":{"en":"Mrs. Baylor strode to the elevator and punched the button.","cn":"贝勒太太迈向电梯，按下按钮。"}},{"pos":"VERB 动词","cn":"戳，刺（洞）","en":"If you punch holes in something, you make holes in it by pushing or pressing it with something sharp.","ex":{"en":"I took a ballpoint pen and punched a hole in the carton.","cn":"我拿了一支圆珠笔，在纸盒上戳了一个洞。"}},{"pos":"N-COUNT 可数名词","cn":"打孔机；穿孔器","en":"A punch is a tool that you use for making holes in something.","ex":{"en":"Make two holes with a hole punch.","cn":"用打孔器打两个孔。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"影响力；效力","en":"If you say that something has punch, you mean that it has force or effectiveness.","ex":{"en":"My nervousness made me deliver the vital points of my address without sufficient punch","cn":"我太紧张，没能有效地传达我演说的要点。"}},{"pos":"N-MASS 物质名词","cn":"潘趣酒，宾治酒（各种酒和糖、柠檬、调料等勾兑而成的饮料）","en":"Punch is a drink made from wine or spirits mixed with things such as sugar, lemons, and spices."},{"pos":"PHRASE 短语","cn":"谨慎（或婉转）地批评","en":"If you say that someone does not pull their punches when they are criticizing a person or thing, you mean that they say exactly what they think, even though this might upset or offend people. to pack a punch→see: ;","ex":{"en":"She has a reputation for getting at the guts of a subject and never pulling her punches.","cn":"她论事一针见血是出了名的，从来都是直言不讳。"}},{"pos":"","cn":"","en":"相关词组：punch in"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit someone quickly and hard with your hand, a stick etc","cn":""},{"en":"to hit someone deliberately many times, especially very hard","cn":""},{"en":"to hit someone with your hand or a weapon. Strike is more formal than hit and is mainly used in written English","cn":""}]},"collocations":{"phrases":["ADV. hard | lightly | repeatedly","PREP. in His attacker had punched him hard in the face. | on She punched him on the nose.","PHRASES kick and punch/punch and kick He was repeatedly kicked and punched as he lay on the ground."]},"media":{"img":["media/ldoce/img/hole_punch.jpg"],"uk":"media/ldoce/hwd/bre/8/brelasdepunch.mp3","us":"media/ldoce/hwd/ame/3/punch1.mp3"},"examples":[{"en":"It's a well-constructed crime story, told with speed and punch.","cn":"这篇描写犯罪的故事构思精巧，情节紧凑，引人入胜。"},{"en":"This player seems to be able to constantly punch above his weight.","cn":"这名选手似乎总有本事击败实力比他强的对手。"}],"oxford":{"phon":"pʌntʃ","pos":"verb","senses":[{"en":"to hit somebody/something hard with your fist (= closed hand)","cn":"拳打；以拳痛击","ex":{"en":"He was kicked and punched as he lay on the ground.","cn":"他倒在地上，被拳打脚踢。"}},{"en":"to make a hole in something with a punch or some other sharp object","cn":"给…打孔；（用打孔器等）打孔","ex":{"en":"to punch a time card","cn":"在记时卡上打孔"}},{"en":"to press buttons or keys on a computer, phone, etc. in order to operate it","cn":"按（键）；压（按钮）","ex":{"en":"I punched the button to summon the elevator.","cn":"我按电钮叫电梯。"}},{"en":"a hard hit made with the fist (= closed hand)","cn":"重拳击打；用力的捶打","g":"[countable]","lab":"figurative","ex":{"en":"a punch in the face","cn":"打在脸上的一记重拳"},"pos":"noun"},{"en":"the power to interest people","cn":"吸引力","g":"[uncountable]","ex":{"en":"It's a well-constructed crime story, told with speed and punch.","cn":"这篇描写犯罪的故事构思精巧，情节紧凑，引人入胜。"},"pos":"noun"},{"en":"a tool or machine for cutting holes in paper, leather or metal","cn":"打孔机；穿孔器；冲床","g":"[countable]","ex":{"en":"a hole punch","cn":"打孔器"},"pos":"noun"},{"en":"a hot or cold drink made by mixing water, fruit juice, spices and usually wine or another alcoholic drink","cn":"潘趣酒，宾治酒（用水、果汁、香料及葡萄酒或其他酒类勾兑成的冷或热的饮料）","g":"[uncountable]","pos":"noun"},{"en":"a British humorous magazine, established in 1841, which took its name from the character Punch in Punch and Judy shows. It became Britain's leading magazine for humorous political and social comment, and included drawings by famous artists such as John Tenniel. It was originally published every week. In the 1980s it began losing readers to other magazines such as Private Eye. It stopped appearing in 1992 but appeared again from 1996 to 2002.","cn":"拳打：成立于1841年的英国幽默杂志，其名字取自Punch and Judy节目中的Punch角色。它成为英国有关幽默的政治和社会评论的领先杂志，并收录了John Tenniel等著名艺术家的素描。它最初每周出版一次。在1980年代，它开始使读者流失于《私人眼》等其他杂志。它于1992年停止出现，但从1996年到2002年再次出现。","pos":""}]}},"purity":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality or state of being pure","cn":"纯﹔纯洁﹔洁净﹔纯正﹔纯粹"}]},"vocab":{"pos":"n","senses":[{"en":"Something that exhibits purity hasn't been tainted by something morally or physically. Children, fresh snow, and solid gold are all known for their purity ."}]},"collocations":{"phrases":["ADJ. absolute the absolute purity of her love | great, high high-purity silver | ideological | racial | moral","VERB + PURITY maintain, preserve He struggled to preserve his ideological purity.","PHRASES purity of form/sound/style the building's unadorned purity of style"]},"media":{"uk":"media/ldoce/hwd/bre/c/purity0205.mp3","us":"media/ldoce/hwd/ame/b/purity.mp3"},"examples":[{"en":"The purity of the water is tested regularly.","cn":"水的纯度定期检测。"},{"en":"spiritual purity","cn":"心灵纯洁"}],"oxford":{"phon":"ˈpjʊərəti","pos":"noun","senses":[{"en":"the state or quality of being pure","cn":"纯洁；纯净；纯粹","ex":{"en":"The purity of the water is tested regularly.","cn":"水的纯度定期检测。"}}]}},"puzzled":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迷惑的；困惑的；无法理解的","en":"Someone who is puzzled is confused because they do not understand something.","ex":{"en":"Critics remain puzzled by the British election results","cn":"批评家仍然对英国大选的结果困惑不解。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable to understand what someone is saying or what is happening","cn":""},{"en":"confused because you cannot understand something, especially because it is different from what you expect","cn":""},{"en":"very confused and unable to understand something, even though you have tried hard for a long time","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | become, get beginning to get a bit puzzled | remain","ADV. extremely, very | a bit, faintly, a little, rather, slightly, somewhat | genuinely | clearly, obviously","PREP. about You look very puzzled about something. | at I was somewhat puzzled at his unwillingness to help. | by Mrs Sykes seemed slightly "]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdepuzzled.mp3","us":"media/ldoce/hwd/ame/8/laadpuzzled.mp3"},"examples":[{"en":"Scientists are puzzled as to why the whale had swum to the shore.","cn":"科学家们感到不解：为什么这头鲸游到海岸上来。"},{"en":"He looked puzzled so I repeated the question.","cn":"他好像没听懂，于是我把问题又重复了一遍。"}],"oxford":{"phon":"ˈpʌzld","pos":"adjective","senses":[{"en":"unable to understand something or the reason for something","cn":"困惑的；迷惑不解的","ex":{"en":"She had a puzzled look on her face.","cn":"她满脸困惑的表情。"}}]},"base":"puzzle"},"puberty":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"青春期；发育期","en":"Puberty is the stage in someone's life when their body starts to become physically mature.","ex":{"en":"Margaret had reached the age of puberty.","cn":"玛格丽特已到了青春期。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the stage of physical development during which you change from a child to an adult and are able to have children","cn":"青春期"}]},"vocab":{"pos":"n","senses":[{"en":"Puberty is a time of life when your sex organs start working like an adult's. During puberty , girls and boys start to become women and men."}]},"collocations":{"phrases":["VERB + PUBERTY reach He reached puberty at the age of fourteen. | approach","PREP. at ~ Girls start menstruating at puberty. | during ~ The body undergoes many changes during puberty.","PHRASES the age of puberty, the onset of puberty"]},"media":{"uk":"media/ldoce/hwd/bre/6/puberty0205.mp3","us":"media/ldoce/hwd/ame/4/puberty.mp3"},"examples":[{"en":"to reach puberty","cn":"进入青春期"},{"en":"Fourteen is a fairly normal age for a girl to reach puberty . 14","cn":"岁是女孩进入青春期相当正常的一个年龄。"}],"oxford":{"phon":"ˈpjuːbəti","pos":"noun","senses":[{"en":"the period of a person’s life during which their sexual organs develop and they become capable of having children","cn":"青春期","lab":"often ironic) 102／23 （） 102／23 （）","ex":{"en":"to reach puberty","cn":"进入青春期"}}]}},"puncture":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an empty space in the surface of something, which sometimes goes all the way through it","cn":""},{"en":"an empty area between two things, into which you can put something","cn":""},{"en":"an empty area between two things or two parts of something, especially one that should not be there","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you puncture something, you make a hole in it. Stick a pin in a balloon and you'll not only make kids cry, you'll also puncture the balloon."}]},"collocations":{"phrases":["ADJ. slow The tyre had a slow puncture and had to be pumped up every day. | bicycle","VERB + PUNCTURE get, have, suffer She suffered a puncture in the fifth lap. | fix, mend, repair"]},"media":{"uk":"media/ldoce/hwd/bre/2/puncture_v0205.mp3","us":"media/ldoce/hwd/ame/4/puncture1.mp3"},"examples":[{"en":"She was taken to the hospital with broken ribs and a punctured lung.","cn":"她肋骨骨折、肺部穿孔，被送往医院。"},{"en":"I had a puncture on the way and arrived late.","cn":"我在路上扎破了轮胎，所以迟到了。"}],"oxford":{"phon":"ˈpʌŋktʃə(r)","pos":"noun","senses":[{"en":"a small hole in a tyre made by a sharp point that allows air to escape","cn":"（轮胎上刺破的）小孔，小洞","lab":"British English","ex":{"en":"I had a puncture on the way and arrived late.","cn":"我在路上扎破了轮胎，所以迟到了。"}},{"en":"a small hole, especially in the skin, made by a sharp point","cn":"（尤指皮肤上被刺破的）扎孔；刺伤","ex":{"en":"There were four small puncture marks on her wrist where the cat had bitten her.","cn":"她的手腕上有四个被猫咬伤的小刺痕。"}},{"en":"to make a small hole in something; to get a small hole","cn":"在…上扎孔（或穿孔）；（被）刺破","g":"[transitive, intransitive]","ex":{"en":"to puncture a tyre","cn":"扎破轮胎"},"pos":"verb"},{"en":"to suddenly make somebody feel less confident, proud, etc.","cn":"使突然泄气；挫伤（锐气等）","g":"[transitive]","ex":{"en":"to puncture somebody’s confidence","cn":"打击某人的信心"},"pos":"verb"}]}}});
